  // src/js/brs/core/recipient.ts
  function automaticallyCheckRecipient() {
    const recipientFieldIds = [
      "#add_asset_treasury_account_recipient",
      "#add_contact_account_id",
      "#update_contact_account_id",
      "#buy_alias_recipient",
      "#escrow_create_recipient",
      "#inline_message_recipient",
      "#reward_assignment_recipient",
      "#sell_alias_recipient",
      "#send_message_recipient",
      "#send_money_recipient",
      "#subscription_cancel_recipient",
      "#subscription_create_recipient",
      "#transfer_alias_recipient",
      "#transfer_asset_recipient",
      "#transfer_asset_multi_recipient",
      "#transfer_asset_ownership_recipient"
    ];
    const $recipientFields = $(recipientFieldIds.join(", "));
    $recipientFields.on("blur", function() {
      $(this).trigger("checkRecipientEvent");
    });
    $recipientFields.on("checkRecipientEvent", function() {
      const value = $(this).val();
      const form = $(this).closest("form");
      if (value) {
        checkRecipient(String(value), form);
      } else {
        form.find(".account_info").hide();
      }
    });
  }
  async function getAccountTypeAndMessage(accountIdOrRs) {
    if (accountIdOrRs === "0" || accountIdOrRs.endsWith("2222-2222-2222-22222")) {
      return {
        type: "warning",
        message: $.t("recipient_burning_address"),
        account: null,
        publicKeyNeeded: "hide"
      };
    }
    const response = await sendRequest("getAccount", { account: accountIdOrRs });
    if (isErrorResponse(response)) {
      switch (response.errorCode) {
        case 4:
          return {
            type: "danger",
            message: $.t("recipient_malformed"),
            account: null,
            publicKeyNeeded: "hide"
          };
        case 5:
          return {
            type: "warning",
            message: $.t("recipient_unknown_pka"),
            account: null,
            publicKeyNeeded: "needed"
          };
      }
      return {
        type: "danger",
        message: $.t("recipient_problem") + " " + response.errorDescription,
        account: null,
        publicKeyNeeded: "hide"
      };
    }
    if (response.isAT) {
      return {
        type: "info",
        message: $.t("recipient_smart_contract", {
          burst: formatNQTAsAmount(response.balanceNQT),
          valueSuffix: BRS.valueSuffix
        }),
        account: response,
        publicKeyNeeded: "hide"
      };
    }
    if (response.isSecured === false) {
      return {
        type: "warning",
        message: $.t("recipient_no_public_key", {
          burst: formatNQTAsAmount(response.unconfirmedBalanceNQT),
          valueSuffix: BRS.valueSuffix
        }),
        account: response,
        publicKeyNeeded: "needed"
      };
    }
    return {
      type: "info",
      message: $.t("recipient_info", {
        burst: formatNQTAsAmount(response.unconfirmedBalanceNQT),
        valueSuffix: BRS.valueSuffix
      }),
      account: response,
      publicKeyNeeded: "info"
    };
  }
  function evMalformedAddressClick(el) {
    $(el.currentTarget).closest("form").find("input[name=recipient],input[name=account_id]").val($(el.currentTarget).data("address")).trigger("blur");
  }
  function formatRecipientPublicKey(toType, form, publicKey) {
    switch (toType) {
      case "needed":
        form.find("input[name=recipientPublicKey]").val("").prop("disabled", false);
        form.find(".recipient_public_key").show();
        break;
      case "hide":
        form.find("input[name=recipientPublicKey]").val("").prop("disabled", false);
        form.find(".recipient_public_key").hide();
        break;
      default:
        form.find("input[name=recipientPublicKey]").val(publicKey ?? "").prop("disabled", true);
        form.find(".recipient_public_key").show();
    }
  }
  async function checkRecipient(account, form) {
    const callout = form.find(".account_info").first();
    const accountInputField = form.find("input[name=converted_account_id]");
    const merchantInfoField = form.find("input[name=merchant_info]");
    accountInputField.val("");
    merchantInfoField.val("");
    account = account.trim();
    const accountParts = BRS.rsRegEx.exec(account);
    if (accountParts !== null) {
      const address = new NxtAddress(accountParts[2]);
      if (address.isOk()) {
        if (accountParts[3] !== void 0) {
          const publicKey = convertPublicKeyFromBase36ToBase16(accountParts[3]);
          const checkRS = getAccountIdFromPublicKey(publicKey, true);
          if (!checkRS.includes(accountParts[2])) {
            formatRecipientPublicKey("hide", form);
            updateCallout(callout, "alert-danger", $.t("recipient_malformed"));
            return;
          }
          const response2 = await getAccountTypeAndMessage(address.getAccountId());
          if (!response2.account) {
            formatRecipientPublicKey("info", form, publicKey);
            updateCallout(callout, "alert-" + response2.type, $.t("recipient_info_extended") + " " + response2.message);
            return;
          }
          if (response2.account.publicKey && response2.account.publicKey !== publicKey) {
            formatRecipientPublicKey("hide", form);
            updateCallout(callout, "alert-danger", $.t("error_public_key_different_account_id"));
            return;
          }
          checkForMerchant(response2.account?.description, form);
          formatRecipientPublicKey("info", form, publicKey);
          updateCallout(callout, "alert-" + response2.type, $.t("recipient_info_extended") + " " + response2.message);
          return;
        }
        const response = await getAccountTypeAndMessage(address.getAccountId());
        formatRecipientPublicKey(response.publicKeyNeeded, form, response.account?.publicKey);
        checkForMerchant(response.account?.description, form);
        updateCallout(callout, "alert-" + response.type, response.message);
        return;
      }
      const guessedAddresses = address.getGuesses(BRS.prefix);
      if (guessedAddresses.length > 0) {
        let html = $.t("recipient_malformed_suggestion_plural") + "<ul>";
        for (const guess of guessedAddresses) {
          html += `
                    <li>
                      <span
                        class='malformed_address pointer'
                        data-address='${guess}'>
                        ${address.formatGuess(guess, account)}
                      </span>
                    </li>`;
        }
        html += "</ul>";
        updateCallout(callout, "alert-danger", html);
        callout.find(".malformed_address").on("click", evMalformedAddressClick);
        return;
      }
      updateCallout(callout, "alert-danger", $.t("recipient_malformed"));
      return;
    }
    if (BRS.idRegEx.test(account)) {
      const response = await getAccountTypeAndMessage(account);
      formatRecipientPublicKey(response.publicKeyNeeded, form, response.account?.publicKey);
      updateCallout(callout, "alert-" + response.type, response.message);
      return;
    }
    if (account.charAt(0) === "@") {
      checkRecipientAlias(account.substring(1), form);
      return;
    }
    const contact = getContactByName(account);
    if (contact) {
      const response = await getAccountTypeAndMessage(contact.account);
      formatRecipientPublicKey(response.publicKeyNeeded, form, response.account?.publicKey);
      checkForMerchant(response.account?.description, form);
      const message = $.t("contact_account_link", { account_id: getAccountRSFromObject(contact, "account") }) + " " + response.message;
      updateCallout(callout, "alert-" + response.type, message);
      if (response.type === "info" || response.type === "warning") {
        accountInputField.val(contact.accountRS);
      }
      return;
    }
    const msg = $.t("name_not_in_contacts", { name: account }) + " " + $.t("recipient_alias_suggestion");
    updateCallout(callout, "alert-danger", msg);
  }
  async function checkRecipientAlias(account, form) {
    const callout = form.find(".account_info").first();
    const accountInputField = form.find("input[name=converted_account_id]");
    accountInputField.val("");
    const response = await sendRequest("getAlias", { aliasName: account });
    if (response.errorCode) {
      updateCallout(callout, "alert-danger", $.t("error_invalid_alias_name"));
      return;
    }
    if (response.aliasURI) {
      const alias = String(response.aliasURI);
      const timestamp = response.timestamp;
      const regex_1 = /acct:(.*)@burst/;
      const regex_2 = /nacc:(.*)/;
      const match = alias.match(regex_1) || alias.match(regex_2);
      if (match && match[1]) {
        const address = new NxtAddress(String(match[1]).toUpperCase());
        if (!address.isOk()) {
          updateCallout(callout, "alert-danger", $.t("invalid_account_alias"));
          return;
        }
        const response2 = await getAccountTypeAndMessage(address.getAccountId());
        formatRecipientPublicKey(response2.publicKeyNeeded, form, response2.account?.publicKey);
        checkForMerchant(response2.account?.description, form);
        accountInputField.val(address.getAccountRS(BRS.prefix));
        let text = $.t("alias_account_link", { account_id: address.getAccountRS(BRS.prefix) });
        text += ".<br>";
        text += $.t("alias_last_adjusted", { timestamp: formatTimestampAsDateTime(timestamp) });
        text += `<br>${response2.message}`;
        updateCallout(callout, "alert-" + response2.type, text);
        return;
      }
      let msg2 = $.t("alias_account_no_link");
      msg2 += !alias ? $.t("error_uri_empty") : $.t("uri_is", { uri: alias });
      updateCallout(callout, "alert-danger", msg2);
      return;
    }
    if (response.aliasName) {
      updateCallout(callout, "alert-danger", $.t("error_alias_empty_uri"));
      return;
    }
    const msg = response.errorDescription ? $.t("error") + ": " + response.errorDescription : $.t("error_alias");
    updateCallout(callout, "alert-danger", msg);
  }
  function updateCallout(callout, alertClass, message) {
    callout.removeClass("alert-info alert-danger alert-warning").addClass(alertClass).html(message).show();
    if (alertClass === "alert-danger") {
      callout.closest("form").find('input[name="recipient"]').addClass("is-invalid");
    } else {
      callout.closest("form").find('input[name="recipient"]').removeClass("is-invalid");
    }
  }
  function checkForMerchant(accountInfo, form) {
    if (!accountInfo) return;
    const requestType = form.find("input[name=request_type]").val();
    if (requestType !== "sendMoney" && requestType !== "transferAsset") {
      return;
    }
    if (!accountInfo.match(/merchant/i)) {
      return;
    }
    form.find("input[name=merchant_info]").val(accountInfo);
    const checkbox = form.find("input[name=add_message]");
    if (!checkbox.is(":checked")) {
      checkbox.prop("checked", true).trigger("change");
    }
  }
  function evRecipientSelectorClickUlLiA(e) {
    const element = e.target;
    e.preventDefault();
    $(element).closest("form").find("input[name=converted_account_id]").val("");
    $(element).closest(".input-group").find("input").not("[type=hidden]").val($(element).data("contact")).trigger("blur");
  }
  function evAddRecipientsClick(e) {
    e.preventDefault();
    let $newRecipient;
    if ($("#send_money_same_out_checkbox").is(":checked")) {
      $newRecipient = $("#multi_out_same_recipients").append($("#additional_multi_out_same_recipient").html());
      $newRecipient = $newRecipient.children().last();
    } else {
      $newRecipient = $("#multi_out_recipients").append($("#additional_multi_out_recipient").html());
      $newRecipient = $newRecipient.children().last();
    }
    $newRecipient.find("input[name=recipient_multi_out_same]").on("blur", evMultiOutSameAmountChange);
    $newRecipient.find("input[name=recipient_multi_out]").on("blur", evMultiOutAmountChange);
    $newRecipient.find("input[name=amount_multi_out]").on("blur", evMultiOutAmountChange);
    $newRecipient.find(".ev-check-number-input").on("input", evCheckNumberInput);
    $newRecipient.find(".remove_recipient_button").on("click", evDocumentOnClickRemoveRecipient);
    $newRecipient.find(".recipient_selector ul li a").on("click", evRecipientSelectorClickUlLiA);
  }
  function populateRecipientSelector($place) {
    const $allList = $place.find(".recipient_selector ul");
    if ($allList.length === 0) {
      return;
    }
    for (const list of $allList) {
      const $list = $(list);
      if (!Object.keys(BRS.contacts).length) {
        $list.html(`<li><a class='dropdown-item' href='#' data-contact=''>${$.t("error_no_contacts_available")}</a></li>`);
        return;
      }
      $list.empty();
      const names = [];
      for (const accountId in BRS.contacts) {
        names.push(BRS.contacts[accountId].name);
      }
      names.sort((a, b) => {
        const nameA = a.toUpperCase();
        const nameB = b.toUpperCase();
        if (nameA < nameB) return -1;
        if (nameA > nameB) return 1;
        return 0;
      });
      for (const name of names) {
        $list.append(`<li><a class='dropdown-item' href='#' data-contact='${name.escapeHTML()}'>${name.escapeHTML()}</a></li>`);
      }
      $list.on("click", "li a", evRecipientSelectorClickUlLiA);
    }
  }
  function evDocumentOnClickRemoveRecipient(e) {
    const element = e.target;
    e.preventDefault();
    $(element).closest(".row").remove();
    if ($("#send_money_same_out_checkbox").is(":checked")) {
      evMultiOutSameAmountChange();
    } else {
      evMultiOutAmountChange();
    }
  }

  // src/js/brs/pages/assets.asset_exchange.ts
  function pagesAssetExchange() {
    if (BRS.currentSubPage) {
      updateMiniTradeHistory();
      return;
    }
    $("#asset_details").hide();
    loadAssetExchangeSidebar();
  }
  async function bookmarkAllUserAssets() {
    const assetsToBookmark = [];
    const idsToFetchAndBookmark = [];
    if (!BRS.accountInfo.unconfirmedAssetBalances) {
      return;
    }
    if (BRS.requestController?.getPendingRequestsCount()) {
      notify($.t("asset_data_loading"));
      await sendRequest("getBlockchainStatus+", {});
    }
    for (const userAsset of BRS.accountInfo.unconfirmedAssetBalances) {
      const foundAsset = BRS.assets.find((tkn) => tkn.asset === userAsset.asset);
      if (foundAsset) {
        assetsToBookmark.push(foundAsset);
      } else {
        idsToFetchAndBookmark.push(userAsset.asset);
      }
    }
    if (assetsToBookmark.length + idsToFetchAndBookmark.length === 0) {
      return;
    }
    for (const eachAsset of idsToFetchAndBookmark) {
      sendRequest("getAsset+", {
        asset: eachAsset
      }).then((response) => {
        if (!response.errorCode) {
          cacheAsset(response);
        }
      });
    }
    if (idsToFetchAndBookmark.length) {
      notify($.t("error_unknown"), {
        type: "danger"
      });
    }
    saveAssetBookmarks(assetsToBookmark, notifyAndGoToAsset);
  }
  async function formsAddAssetBookmark(data) {
    data.id = data.id.trim();
    if (!data.id) {
      return {
        error: $.t("error_asset_or_account_id_required")
      };
    }
    if (!BRS.idRegEx.test(data.id)) {
      return {
        error: $.t("no_asset_found")
      };
    }
    const foundAsset = await getAssetDetails(data.id);
    if (foundAsset === void 0) {
      return {
        error: $.t("no_asset_found")
      };
    }
    saveAssetBookmarks([foundAsset], notifyAndGoToAsset);
    return { stop: true, hide: true };
  }
  function notifyAndGoToAsset(newAssets, submittedAssets) {
    BRS.assetSearch = false;
    if (newAssets.length === 0) {
      notify(
        $.t("error_asset_already_bookmarked", {
          count: submittedAssets.length
        }),
        { type: "danger" }
      );
      goToAsset(submittedAssets[0].asset);
    } else if (newAssets.length === 1) {
      notify($.t("success_asset_bookmarked"), { type: "success" });
      goToAsset(newAssets[0].asset);
    } else {
      notify($.t("success_asset_bookmarked_plural"), { type: "success" });
      goToAsset(newAssets[0].asset);
    }
  }
  function saveAssetBookmarks(assets, callback) {
    const newAssets = [];
    for (const asset of assets) {
      const foundAsset = BRS.assets.find((Obj) => Obj.asset === asset.asset);
      if (foundAsset) {
        if (foundAsset.bookmarked === false) {
          foundAsset.bookmarked = true;
          newAssets.push(foundAsset);
        }
      }
    }
    if (BRS.databaseSupport) {
      dbPut("assets", newAssets);
    }
    if (callback) {
      callback(newAssets, assets);
    }
  }
  function createBookmarkSidebarHTMLItem(asset, quantityHTML) {
    if (quantityHTML === "0") {
      return asset.name + "<br>&nbsp;";
    }
    return `${asset.name}<br><small>${$.t("quantity_abbr")}: ${quantityHTML}</small>`;
  }
  function updateQuantitiesInAssetExchangeSidebarContent() {
    $("#asset_exchange_vtab  a").each(function() {
      const $eachElement = $(this);
      const assetId = $eachElement.data("asset");
      if (!assetId) {
        return;
      }
      getAssetDetails(assetId).then((asset) => {
        if (!asset) {
          return;
        }
        const accountAsset = BRS.accountInfo.assetBalances?.find((Obj) => Obj.asset === asset.asset);
        const userAssetQuantity = accountAsset === void 0 ? "0" : formatQNTAsQuantity(accountAsset.balanceQNT, asset.decimals);
        $eachElement.html(createBookmarkSidebarHTMLItem(asset, userAssetQuantity));
        if (userAssetQuantity === "0") {
          $eachElement.addClass("not_owns_asset").removeClass("owns_asset");
        } else {
          $eachElement.addClass("owns_asset").removeClass("not_owns_asset");
        }
      });
    });
  }
  function loadAssetExchangeSidebar(callback) {
    const bookmarkedAssets = BRS.assets.filter((token) => token.bookmarked === true);
    let rows = "";
    $("#asset_exchange_page").removeClass("no_assets");
    bookmarkedAssets.sort(function(a, b) {
      if (!a.groupName && !b.groupName) {
        return a.name.localeCompare(b.name);
      } else if (!a.groupName) {
        return 1;
      } else if (!b.groupName) {
        return -1;
      } else if (a.groupName > b.groupName) {
        return 1;
      } else if (a.groupName < b.groupName) {
        return -1;
      } else {
        return a.name.localeCompare(b.name);
      }
    });
    let lastGroup = "";
    let ungrouped = true;
    let isClosedGroup = false;
    for (const asset of bookmarkedAssets) {
      if (BRS.assetSearch !== false && BRS.assetSearch.indexOf(asset.asset) === -1) {
        continue;
      }
      if (asset.groupName !== lastGroup) {
        lastGroup = asset.groupName;
        const to_check = asset.groupName ? asset.groupName : "undefined";
        if (BRS.closedGroups.indexOf(to_check) !== -1) {
          isClosedGroup = true;
        } else {
          isClosedGroup = false;
        }
        const angleDirection = isClosedGroup ? "right" : "down";
        if (asset.groupName) {
          ungrouped = false;
          rows += `
                    <a href='#'
                    class='nav-link list-group-item-action'
                    data-context='asset_exchange_vtab_group_context'
                    data-item='${asset.groupName.escapeHTML()}'
                    data-closed='${isClosedGroup}'>
                        <strong>
                            ${asset.groupName.escapeHTML()}
                            <i class='right fas pull-right fa-angle-${angleDirection}'></i>
                        </strong>
                    </a>`;
        } else {
          ungrouped = true;
          rows += `
                    <a href='#' 
                    class='nav-link list-group-item-action no-context' 
                    data-closed='${isClosedGroup}'>
                        <strong class='list-group-item-heading'>
                            ${$.t("others")}
                            <i class='right fa pull-right fa-angle-${angleDirection}'></i>
                        </strong>
                    </a>`;
        }
      }
      const accountAsset = BRS.accountInfo.assetBalances?.find((Obj) => Obj.asset === asset.asset);
      const userAssetQuantity = accountAsset === void 0 ? "0" : formatQNTAsQuantity(accountAsset.balanceQNT, asset.decimals);
      let itemClass = "nav-link list-group-item-";
      itemClass += ungrouped ? "ungrouped" : "grouped";
      itemClass += userAssetQuantity === "0" ? " not_owns_asset" : " owns_asset";
      const dataGroupname = ungrouped ? "" : ` data-groupname="${asset.groupName.escapeHTML()}"`;
      const hideClosedGroup = isClosedGroup ? 'style="display:none"' : "";
      rows += `
            
            <a href='#page=asset_exchange&subPage=${asset.asset}'
            class='${itemClass}'
            data-item='${asset.asset}'
            data-context='asset_exchange_vtab_context'
            ${dataGroupname}
            ${hideClosedGroup}
            data-closed='${isClosedGroup}'>
                ${createBookmarkSidebarHTMLItem(asset, userAssetQuantity)}
            </a>`;
    }
    $("#asset_exchange_vtab").html(rows);
    $("#asset_exchange_vtab_search").show();
    if (BRS.assetSearch !== false) {
      if (BRS.currentSubPage && BRS.assetSearch.indexOf(BRS.currentSubPage) !== -1) {
        $("#asset_exchange_vtab a[data-item=" + BRS.currentSubPage + "]").addClass("active");
      } else if (BRS.assetSearch.length === 1) {
        $("#asset_exchange_vtab a[data-item=" + BRS.assetSearch[0] + "]").addClass("active").trigger("click");
      }
    } else if (BRS.currentSubPage) {
      $("#asset_exchange_vtab a[data-item=" + BRS.currentSubPage + "]").addClass("active");
    }
    if (BRS.assetSearch !== false || bookmarkedAssets.length >= 10) {
      $("#asset_exchange_vtab_search").show();
    } else {
      $("#asset_exchange_vtab_search").hide();
    }
    if (BRS.assetSearch !== false && BRS.assetSearch.length === 0) {
      $("#no_asset_search_results").show();
      $("#asset_details, #no_asset_selected, #no_assets_available").hide();
    } else if (!bookmarkedAssets.length) {
      $("#no_asset_selected, #loading_asset_data, #no_asset_search_results, #asset_details").hide();
      $("#no_assets_available").show();
    } else if (!BRS.currentSubPage) {
      $("#no_asset_selected").show();
      $("#asset_details, #no_assets_available, #no_asset_search_results").hide();
    } else {
      $("#no_assets_available, #no_asset_selected, #no_asset_search_results").hide();
    }
    $("#asset_exchange_bookmark_this_asset").hide();
    showHideBookmarkAllAssetsButton();
    pageLoaded(callback);
  }
  function incomingAssetExchange() {
    loadAsset(BRS.currentAsset, false, true);
    updateQuantitiesInAssetExchangeSidebarContent();
  }
  function evAssetExchangeSidebarClick(e) {
    const $element = $(e.currentTarget);
    let group = $element.data("groupname");
    const closed = $element.data("closed");
    if (!$element.hasClass("list-group-item-action")) {
      return;
    }
    e.preventDefault();
    let $links;
    if (!group) {
      $links = $("#asset_exchange_vtab a.list-group-item-ungrouped");
    } else {
      $links = $("#asset_exchange_vtab a.list-group-item-grouped[data-groupname='" + group.escapeHTML() + "']");
    }
    if (!group) {
      group = "undefined";
    }
    if (closed) {
      const pos = BRS.closedGroups.indexOf(group);
      if (pos >= 0) {
        BRS.closedGroups.splice(pos);
      }
      $element.data("closed", "");
      $element.find("i").removeClass("fa-angle-right").addClass("fa-angle-down");
      $links.show();
    } else {
      BRS.closedGroups.push(group);
      $element.data("closed", true);
      $element.find("i").removeClass("fa-angle-down").addClass("fa-angle-right");
      $links.hide();
    }
    if (BRS.databaseSupport) {
      dbPut("data", {
        id: "closed_groups",
        contents: BRS.closedGroups.join("#")
      });
    }
  }
  async function loadAssetExchangeSubPage(asset) {
    if (!asset) return;
    const foundAsset = BRS.assets.find((tkn) => tkn.asset === asset);
    if (foundAsset) {
      loadAsset(foundAsset, true, true);
      return;
    }
    const response = await sendRequest("getAsset+", { asset });
    if (!response.errorCode && response.asset === asset) {
      const addedAsset = cacheAsset(response);
      loadAsset(addedAsset, true, false);
      return;
    }
    notify($.t("invalid_asset"));
  }
  function loadAsset(asset, refreshHTML, refreshAsset) {
    if (!asset?.asset) {
      return;
    }
    const assetId = asset.asset;
    BRS.currentSubPage = asset.asset;
    BRS.currentAsset = asset;
    if (refreshHTML) {
      $("#asset_exchange_vtab a.active").removeClass("active");
      $("#asset_exchange_vtab a[data-item=" + assetId + "]").addClass("active");
      $("#no_asset_selected, #loading_asset_data, #no_assets_available, #no_asset_search_results").hide();
      $("#asset_details").show().parent().animate(
        {
          scrollTop: 0
        },
        0
      );
      $("#asset_account").html(
        "<a href='#modal=user_info&user=" + getAccountRSFromObject(asset, "account") + "'>" + getAccountTitleFromObject(asset, "account") + "</a>"
      );
      $("#asset_id").html(assetId);
      $("#asset_decimals").html(String(asset.decimals));
      $("#asset_name").html(asset.name);
      $("#asset_description").html(asset.description);
      $("#asset_quantity").html(formatQNTAsQuantity(asset.quantityCirculatingQNT, asset.decimals));
      $("#asset_mintable").text(asset.mintable ? $.t("yes") : $.t("no"));
      $("#asset_holders_text").html(`
            <a href="#modal=asset_holders&asset=${asset.asset}">${$.t("view_more")}</a>
            `);
      $(".asset_name").html(asset.name);
      $("#sell_asset_button").attr("href", `#modal=asset_order&asset=${assetId}&type=sell`);
      $("#buy_asset_button").attr("href", `#modal=asset_order&asset=${assetId}&type=buy`);
      $("#sell_asset_for_burst").html(
        $.t("sell_asset_for_burst", {
          assetName: asset.name,
          valueSuffix: BRS.valueSuffix
        })
      );
      $("#buy_asset_with_burst").html(
        $.t("buy_asset_with_burst", {
          assetName: asset.name,
          valueSuffix: BRS.valueSuffix
        })
      );
      $("#sell_asset_price, #buy_asset_price").val("");
      $("#sell_asset_quantity, #sell_asset_total, #buy_asset_quantity, #buy_asset_total").val("0");
      $("#asset_exchange_ask_orders_table tbody").empty();
      $("#asset_exchange_bid_orders_table tbody").empty();
      $("#asset_exchange_trade_history_table tbody").empty();
      $("#asset_exchange_ask_orders_table").parent().addClass("data-loading").removeClass("data-empty");
      $("#asset_exchange_bid_orders_table").parent().addClass("data-loading").removeClass("data-empty");
      $("#asset_exchange_trade_history_table").parent().addClass("data-loading").removeClass("data-empty");
      $(".data-loading img.loading").hide();
      setTimeout(function() {
        $(".data-loading img.loading").fadeIn(200);
      }, 200);
      let nrDuplicates = 0;
      $.each(BRS.assets, function(key, singleAsset) {
        if (String(singleAsset.name) === String(asset.name) && singleAsset.asset !== assetId) {
          nrDuplicates++;
        }
      });
      $("#asset_exchange_duplicates_warning").html(
        $.t("asset_exchange_duplicates_warning", {
          count: nrDuplicates
        })
      );
      if (asset.bookmarked) {
        $("#asset_exchange_bookmark_this_asset").hide();
      } else {
        $("#asset_exchange_bookmark_this_asset").show();
        $("#asset_exchange_bookmark_this_asset").data("assetId", assetId);
      }
      showHideBookmarkAllAssetsButton();
    }
    if (refreshAsset) {
      sendRequest("getAsset+", {
        asset: assetId
      }).then((response) => {
        if (!response.errorCode) {
          cacheAsset(response);
          $("#asset_quantity").html(formatQNTAsQuantity(response.quantityCirculatingQNT, response.decimals));
        } else {
          $("#asset_exchange_vtab a.active").removeClass("active");
          $("#no_asset_selected").show();
          $("#asset_details, #no_assets_available, #no_asset_search_results").hide();
          notify($.t("invalid_asset"), { type: "danger" });
        }
      });
    }
    let userAssetBlance = "0";
    if (BRS.accountInfo.unconfirmedAssetBalances) {
      for (const balance of BRS.accountInfo.unconfirmedAssetBalances) {
        if (balance.asset !== assetId) {
          continue;
        }
        userAssetBlance = balance.unconfirmedBalanceQNT;
        break;
      }
    }
    $("#your_asset_balance").html(formatQNTAsQuantity(userAssetBlance, BRS.currentAsset.decimals));
    $("#your_burst_balance").html(formatNQTAsAmount(BRS.accountInfo.unconfirmedBalanceNQT));
    window.scrollTo({
      top: 0,
      behavior: "smooth"
    });
    loadAssetOrders("ask", assetId, refreshHTML || refreshAsset);
    loadAssetOrders("bid", assetId, refreshHTML || refreshAsset);
    updateMiniTradeHistory();
  }
  function showHideBookmarkAllAssetsButton() {
    if (!BRS.accountInfo.assetBalances) {
      $("#asset_exchange_add_all_assets_bookmark").hide();
      return;
    }
    let show = false;
    for (const userAsset of BRS.accountInfo.assetBalances) {
      if (BRS.assets.findIndex((tkn) => tkn.asset === userAsset.asset && tkn.bookmarked === true) === -1) {
        show = true;
        break;
      }
    }
    if (show) $("#asset_exchange_add_all_assets_bookmark").show();
    else $("#asset_exchange_add_all_assets_bookmark").hide();
  }
  async function updateMiniTradeHistory() {
    const myTrades = $("#ae_show_my_trades_only").is(":checked");
    const response = await sendRequest("getTrades+", {
      asset: BRS.currentAsset.asset,
      account: myTrades ? BRS.account : "",
      firstIndex: BRS.pageSize * (BRS.pageNumber - 1),
      lastIndex: BRS.pageSize * BRS.pageNumber
    });
    if (!response.trades || !response.trades.length) {
      BRS.hasMorePages = false;
      $("#asset_exchange_trade_history_table tbody").empty();
      dataLoadFinished($("#asset_exchange_trade_history_table"), true);
      pageLoaded();
      return;
    }
    if (response.trades.length > BRS.pageSize) {
      BRS.hasMorePages = true;
      response.trades.pop();
    }
    let rows = "";
    for (const trade of response.trades) {
      const totalNQT = calculateOrderTotalNQT(trade.priceNQT, trade.quantityQNT);
      rows += `
            <tr>
              <td>${formatTimestampAsDateTime(trade.timestamp)}</td>
              <td>${formatQNTAsQuantity(trade.quantityQNT, BRS.currentAsset.decimals)}</td>
              <td class='asset_price'>${formatPriceNQTAsPriceQuantity(trade.priceNQT, BRS.currentAsset.decimals)}</td>
              <td>${formatNQTAsAmount(totalNQT)}</td>
              <td><a href='#modal=transaction_info&transaction=${trade.askOrder}'>${trade.askOrder.slice(0, 8)}...</a></td>
              <td><a href='#modal=transaction_info&transaction=${trade.bidOrder}'>${trade.bidOrder.slice(0, 8)}...</a></td>
            </tr>`;
    }
    $("#asset_exchange_trade_history_table tbody").empty().append(rows);
    dataLoadFinished($("#asset_exchange_trade_history_table"), true);
    pageLoaded();
  }
  async function loadAssetOrders(type, assetId, refresh) {
    const response = await sendRequest("get" + type.capitalize() + "Orders+", {
      asset: assetId,
      firstIndex: 0,
      lastIndex: 49
    });
    let orders = [];
    if (response[type + "Orders"]) {
      orders = response[type + "Orders"];
    }
    let typeAction = "buy";
    if (type === "ask") {
      typeAction = "sell";
    }
    if (BRS.unconfirmedTransactions.length) {
      let added = false;
      for (const unconfirmedTransaction of BRS.unconfirmedTransactions) {
        if (unconfirmedTransaction.type === 2 && (type === "ask" ? unconfirmedTransaction.subtype === 2 : unconfirmedTransaction.subtype === 3) && unconfirmedTransaction.attachment.asset === assetId) {
          orders.push({
            order: unconfirmedTransaction.transaction,
            asset: unconfirmedTransaction.attachment.asset,
            account: unconfirmedTransaction.sender,
            accountRS: unconfirmedTransaction.senderRS,
            quantityQNT: unconfirmedTransaction.attachment.quantityQNT,
            priceNQT: unconfirmedTransaction.attachment.priceNQT,
            height: 0,
            name: "",
            decimals: -1,
            price: "",
            type: unconfirmedTransaction.subtype === 2 ? "ask" : "bid"
          });
          added = true;
        }
      }
      if (added) {
        orders.sort(function(a, b) {
          let invert = 1;
          if (type === "bid") {
            invert = -1;
          }
          const priceA = BigInt(a.priceNQT);
          const priceB = BigInt(b.priceNQT);
          if (priceA > priceB) return 1 * invert;
          if (priceA < priceB) return -1 * invert;
          return 0;
        });
      }
    }
    if (orders.length === 0) {
      $(`#asset_exchange_${type}_orders_table tbody`).empty();
      if (!refresh) {
        $(`#${typeAction}_asset_price`).val("0");
      }
      $(`#${typeAction}_orders_count`).html("");
      dataLoadFinished($(`#asset_exchange_${type}_orders_table`), !refresh);
      return;
    }
    $(`#${typeAction}_orders_count`).html("(" + orders.length + (orders.length === 50 ? "+" : "") + ")");
    let rows = "";
    let first = true;
    for (const order of orders) {
      const totalNQT = calculateOrderTotalNQT(order.quantityQNT, order.priceNQT);
      if (first && !refresh) {
        $(`#${typeAction}_asset_price`).val(formatPriceNQTAsPriceQuantity(order.priceNQT, BRS.currentAsset.decimals));
      }
      const toBeCancelled = hasCancelOrder(order);
      let className = "";
      if (order.account === BRS.account) {
        className += "your-order";
      }
      if (order.height === 0) {
        className += " text-muted";
      }
      if (toBeCancelled) {
        className += " text-line-through";
      }
      let accountHTML = "";
      if (order.height === 0 || toBeCancelled) {
        accountHTML = BRS.pendingTransactionHTML + "&nbsp;";
      }
      if (order.account === BRS.currentAsset.account) {
        accountHTML += $.t("asset_issuer");
      } else {
        accountHTML += getAccountTitleFromObject(order, "account");
      }
      accountHTML = `<a href='#modal=user_info&user=${getAccountRSFromObject(order, "account")}'>${accountHTML}</a>`;
      rows += `
            <tr class='${className}'
              data-transaction='${order.order}'
              data-quantity='${order.quantityQNT.toString()}'
              data-price='${order.priceNQT.toString()}'>`;
      if (type === "ask") {
        rows += `
              <td class='bold red-asset'>${formatPriceNQTAsPriceQuantity(order.priceNQT, BRS.currentAsset.decimals)}</td>
              <td>${formatQNTAsQuantity(order.quantityQNT, BRS.currentAsset.decimals)}</td>
              <td>${formatNQTAsAmount(totalNQT)}</td>
              <td>${accountHTML}</td>
            </tr>`;
      } else {
        rows += `
              <td>${accountHTML}</td>
              <td>${formatNQTAsAmount(totalNQT)}</td>
              <td>${formatQNTAsQuantity(order.quantityQNT, BRS.currentAsset.decimals)}</td>
              <td class='bold green-asset'>${formatPriceNQTAsPriceQuantity(order.priceNQT, BRS.currentAsset.decimals)}</td>
            </tr>`;
      }
      first = false;
    }
    $(`#asset_exchange_${type}_orders_table tbody`).html(rows);
    dataLoadFinished($(`#asset_exchange_${type}_orders_table`), !refresh);
  }
  function hasCancelOrder(order) {
    if (!BRS.unconfirmedTransactions.length) {
      return false;
    }
    for (const unconfirmedTransaction of BRS.unconfirmedTransactions) {
      if (unconfirmedTransaction.type === 2 && (order.type === "ask" ? unconfirmedTransaction.subtype === 4 : unconfirmedTransaction.subtype === 5) && unconfirmedTransaction.attachment.order === order.order) {
        return true;
      }
    }
    return false;
  }
  function evAssetExchangeSearchInput(e) {
    let input = $(e.target).val();
    input = input.toUpperCase();
    if (!input) {
      BRS.assetSearch = false;
      loadAssetExchangeSidebar();
      $("#asset_exchange_clear_search").hide();
      return;
    }
    BRS.assetSearch = [];
    for (const asset of BRS.assets) {
      if (asset.bookmarked === true && (asset.account === input || asset.asset === input || asset.name.toUpperCase().includes(input) || asset.accountRS.includes(input))) {
        BRS.assetSearch.push(asset.asset);
      }
    }
    loadAssetExchangeSidebar();
    $("#asset_exchange_clear_search").show();
  }
  function evAssetExchangeOrdersTableClick(e) {
    const $target = $(e.target);
    if ($target.prop("tagName").toLowerCase() === "a") {
      return;
    }
    const type = $target.closest("table").attr("id") === "asset_exchange_bid_orders_table" ? "sell" : "buy";
    const $tr = $target.closest("tr");
    const priceNQT = String($tr.data("price"));
    const quantityQNT = String($tr.data("quantity"));
    const totalNQT = calculateOrderTotalNQT(quantityQNT, priceNQT);
    $("#" + type + "_asset_price").val(formatPriceNQTAsPriceQuantity(priceNQT, BRS.currentAsset.decimals));
    $("#" + type + "_asset_quantity").val(formatQNTAsQuantity(quantityQNT, BRS.currentAsset.decimals));
    $("#" + type + "_asset_total").val(formatNQTAsAmount(totalNQT));
    if (type === "sell") {
      const balanceNQT = BRS.accountInfo.unconfirmedBalanceNQT ?? "0";
      if (BigInt(totalNQT) > BigInt(balanceNQT)) {
        $("#" + type + "_asset_total").css({
          background: "#ED4348",
          color: "white"
        });
      } else {
        $("#" + type + "_asset_total").css({
          background: "",
          color: ""
        });
      }
    }
    const box = $("#" + type + "_asset_box");
    if (box.hasClass("collapsed-card")) {
      box.removeClass("collapsed-card");
      box.find(".card-body").slideDown();
    }
  }
  function evCalculatePricePreviewInput(e) {
    const orderType = $(e.target).data("type").toLowerCase();
    $("#" + orderType + "_asset_total").val($.t("error"));
    let quantityQNT;
    let priceNQT;
    try {
      quantityQNT = parseQuantityToQNT(String($("#" + orderType + "_asset_quantity").val()), BRS.currentAsset.decimals);
    } catch (e2) {
      $("#" + orderType + "_asset_quantity").addClass("is-invalid");
      notify(e2.message);
      return;
    }
    try {
      priceNQT = parsePriceQuantityToPriceNQT($("#" + orderType + "_asset_price").val(), BRS.currentAsset.decimals);
    } catch (e2) {
      $("#" + orderType + "_asset_price").addClass("is-invalid");
      notify(e2.message);
      return;
    }
    const total = formatOrderTotal(quantityQNT, priceNQT);
    $("#" + orderType + "_asset_total").val(total.toString());
  }
  function assetExchangeVtabContextHandler(option, assetId) {
    const asset = BRS.assets.find((tkn) => tkn.asset === assetId);
    if (!asset) {
      console.error("OPA!");
      return;
    }
    if (option === "add_to_group") {
      $("#asset_exchange_group_asset").val(assetId);
      $("#asset_exchange_group_title").html(asset.name);
      const groupNames = [...new Set(BRS.assets.filter((tkn) => tkn.groupName).map((tkn) => tkn.groupName))];
      groupNames.sort((a, b) => a.localeCompare(b));
      const groupSelect = $("#asset_exchange_group_group");
      groupSelect.empty();
      groupNames.forEach((groupName) => {
        groupSelect.append(
          `<option value='${groupName.escapeHTML()}' ${asset.groupName === groupName ? " selected='selected'" : ""}>${groupName.escapeHTML()}</option>`
        );
      });
      groupSelect.append("<option value='0'" + (!asset.groupName ? " selected='selected'" : "") + "></option>");
      groupSelect.append(`<option value='-1'>${$.t("new_group")}</option>`);
      $("#asset_exchange_group_modal").modal("show");
      return;
    }
    if (option === "remove_from_group") {
      asset.groupName = "";
      dbPut("assets", asset, function(error2) {
        if (error2) {
          notify($.t("error_save_db"), { type: "danger" });
          return;
        }
        loadAssetExchangeSidebar();
        notify($.t("success_asset_group_removal"), { type: "success" });
      });
      return;
    }
    if (option === "remove_from_bookmarks") {
      asset.bookmarked = false;
      dbPut("assets", asset, function(error2) {
        if (error2) {
          notify($.t("error_save_db"), { type: "danger" });
          return;
        }
        loadAssetExchangeSidebar();
        notify($.t("success_asset_bookmark_removal"), { type: "success" });
      });
    }
  }
  function assetExchangeVtabGroupContextHandler(option, item) {
    if (option === "change_group_name") {
      $("#asset_exchange_change_group_name_old_display").html(item.escapeHTML());
      $("#asset_exchange_change_group_name_old").val(item);
      $("#asset_exchange_change_group_name_new").val("");
      $("#asset_exchange_change_group_name_modal").modal("show");
    }
  }
  async function goToAsset(asset) {
    BRS.assetSearch = false;
    $("#asset_exchange_vtab_search input[name=q]").val("");
    $("#asset_exchange_clear_search").hide();
    $("#asset_exchange_vtab a.list-group-item.active").removeClass("active");
    $("#no_asset_selected, #asset_details, #no_assets_available, #no_asset_search_results").hide();
    $("#loading_asset_data").show();
    const foundAsset = BRS.assets.find((tkn) => tkn.asset === asset);
    if (foundAsset) {
      loadAssetExchangeSidebar(function() {
        loadAsset(foundAsset, true, true);
      });
      return;
    }
    const response = await sendRequest("getAsset+", {
      asset
    });
    if (!response.errorCode) {
      const addedAsset = cacheAsset(response);
      loadAssetExchangeSidebar(function() {
        loadAsset(addedAsset, true, false);
      });
      return;
    }
    notify($.t("error_asset_not_found"), { type: "danger" });
    loadAssetExchangeSidebar();
    $("#loading_asset_data").hide();
  }

  // src/js/brs/modals/assets.ts
  function fillAssetSelectorDetails(assetId, assetName, decimals, $formGroup) {
    if (assetId === "") {
      $formGroup.find(`span[name=available]`).empty();
      return;
    }
    $formGroup.find("input[name=asset]").val(assetId);
    $formGroup.find("input[name=decimals]").val(decimals);
    $formGroup.find("span[name=asset-name]").text(assetName);
    $formGroup.find("input[name=name_plus_asset]").val(assetName + " - " + assetId);
    if ($formGroup.closest("form").attr("id") === "form-mint-asset") {
      const selectedAsset = getAssetFromCache(assetId);
      if (!selectedAsset) return;
      $formGroup.find("span[name=available]").text($.t("quantity_circulating") + ": " + formatQNTAsQuantity(selectedAsset.quantityCirculatingQNT, selectedAsset.decimals));
      return;
    }
    let confirmedBalance = "";
    let unconfirmedBalance = "";
    if (BRS.accountInfo.assetBalances) {
      BRS.accountInfo.assetBalances.find((assetBalance) => {
        if (assetBalance.asset === assetId) {
          confirmedBalance = assetBalance.balanceQNT;
          return true;
        }
        return false;
      });
    }
    if (BRS.accountInfo.unconfirmedAssetBalances) {
      BRS.accountInfo.unconfirmedAssetBalances.find((assetBalance) => {
        if (assetBalance.asset === assetId) {
          unconfirmedBalance = assetBalance.unconfirmedBalanceQNT;
          return true;
        }
        return false;
      });
    }
    let availableAssetsMessage = "";
    if (confirmedBalance === unconfirmedBalance) {
      availableAssetsMessage = $.t("available_for_transfer", {
        qty: formatQNTAsQuantity(confirmedBalance, Number(decimals))
      });
    } else {
      availableAssetsMessage = $.t("available_for_transfer", {
        qty: formatQNTAsQuantity(unconfirmedBalance, Number(decimals))
      }) + " (" + formatQNTAsQuantity(confirmedBalance, Number(decimals)) + " " + $.t("total_lowercase") + ")";
    }
    $formGroup.find(`span[name=available]`).html(availableAssetsMessage);
  }
  function showDistributeToAssetHoldersModal(assetId, assetName, decimals) {
    const $formGroup = $("#form-distribute_to_asset_holders").first();
    if (!assetId) {
      $formGroup.find("input[name=holders_asset]").empty().addClass("is-invalid");
    } else {
      $formGroup.find("input[name=holders_asset]").val(assetId).removeClass("is-invalid");
    }
    $formGroup.find("input[name=holders_decimals]").val(decimals);
    $formGroup.find("span[name=holders_asset_name]").text(assetName);
    showModal("distribute_to_asset_holders");
  }
  async function evDistributeToAssetHoldersHoldersAssetInput(e) {
    const assetInput = $(e.target).val();
    const chainAsset = await getAssetDetails(assetInput);
    const $formGroup = $("#form-distribute_to_asset_holders");
    if (!chainAsset) {
      $("#distribute_to_asset_holders_holders_asset").addClass("is-invalid");
      $formGroup.find("input[name=holders_decimals]").empty();
      $formGroup.find("span[name=holders_asset_name]").text("?");
      return;
    }
    $formGroup.find("input[name=holders_asset]").val(chainAsset.asset).removeClass("is-invalid");
    $formGroup.find("input[name=holders_decimals]").val(chainAsset.decimals);
    $formGroup.find("span[name=holders_asset_name]").text(chainAsset.name);
  }
  async function populateReferencedAsset(assetId, formName) {
    $(`#${formName}_name_plus_asset`).val($.t("loading_please_wait")).addClass("is-invalid");
    $(`#${formName}_referenced_transaction`).val($.t("loading_please_wait")).addClass("is-invalid");
    const issueAssetTx = await sendRequest("getTransaction", { transaction: assetId });
    if (issueAssetTx.errorCode) {
      $(`#${formName}_name_plus_asset`).val($.t("error"));
      $(`#${formName}_referenced_transaction`).val($.t("error"));
      return;
    }
    $(`#${formName}_name_plus_asset`).val(assetId + " - " + issueAssetTx.attachment.name).removeClass("is-invalid");
    $(`#${formName}_referenced_transaction`).val(issueAssetTx.fullHash).removeClass("is-invalid");
  }
  function formsTransferAssetOwnership(data) {
    delete data.name_plus_asset;
    return {
      data
    };
  }
  function formsAddAssetTreasuryAccount(data) {
    delete data.name_plus_asset;
    return {
      data
    };
  }
  function formsTransferAssetMulti(data) {
    data.assetIdsAndQuantities = "";
    let items = 0;
    let showWarning = false;
    for (let i = 0; i < 4; i++) {
      if (data.asset[i] === "" || Number(data.quantity[i]) === 0) {
        continue;
      }
      if (items > 0) {
        data.assetIdsAndQuantities += ";";
      }
      items++;
      if (Number(data.quantity[i]) > Number(BRS.settings.asset_transfer_warning) && BRS.settings.asset_transfer_warning !== "0") {
        showWarning = true;
      }
      try {
        data.assetIdsAndQuantities += data.asset[i] + ":" + parseQuantityToQNT(data.quantity[i], Number(data.decimals[i]));
      } catch (e) {
        return {
          error: $.t("error_incorrect_quantity_plus", {
            err: e.message.escapeHTML()
          })
        };
      }
    }
    if (items < 2) {
      return { error: $.t("error_multi_transfer_minimum") };
    }
    delete data.asset;
    delete data.quantity;
    delete data.decimals;
    delete data.name_plus_asset;
    if (!data.amountNXT) {
      data.amountNXT = "0";
    }
    if (!BRS.showedFormWarning && showWarning) {
      BRS.showedFormWarning = true;
      return {
        error: $.t("error_max_asset_transfer_warning", {
          qty: BRS.settings.asset_transfer_warning
        })
      };
    }
    return {
      data
    };
  }
  function formsTransferAsset(data) {
    if (!data.quantity) {
      return {
        error: $.t("error_not_specified", {
          name: getTranslatedFieldName("quantity").toLowerCase()
        }).capitalize()
      };
    }
    if (!data.amountNXT) {
      data.amountNXT = "0";
    }
    if (!BRS.showedFormWarning && BRS.settings.asset_transfer_warning !== "0" && Number(data.quantity) > Number(BRS.settings.asset_transfer_warning)) {
      BRS.showedFormWarning = true;
      return {
        error: $.t("error_max_asset_transfer_warning", {
          qty: BRS.settings.asset_transfer_warning
        })
      };
    }
    try {
      data.quantityQNT = parseQuantityToQNT(data.quantity, Number(data.decimals));
    } catch (e) {
      return {
        error: $.t("error_incorrect_quantity_plus", {
          err: e.message.escapeHTML()
        })
      };
    }
    delete data.quantity;
    delete data.decimals;
    delete data.name_plus_asset;
    return {
      data
    };
  }
  function formsCancelOrder(data) {
    const requestType = data.cancel_order_type;
    delete data.cancel_order_type;
    let successMessage = $.t("success_cancelBuyOrder");
    if (requestType === "cancelAskOrder") {
      successMessage = $.t("success_cancelAskOrder");
    }
    return {
      data,
      requestType,
      successMessage
    };
  }
  function formsAssetExchangeGroup(data) {
    function successMessageAndReloadSidebar() {
      setTimeout(function() {
        loadAssetExchangeSidebar();
        if (!groupName) {
          notify($.t("success_asset_group_removal"), { type: "success" });
        } else {
          notify($.t("success_asset_group_add"), { type: "success" });
        }
      }, 50);
    }
    const assetId = data.asset_exchange_group_asset;
    let groupName = data.asset_exchange_group_group;
    if (groupName === "0") {
      groupName = "";
    } else if (groupName === "-1") {
      groupName = data.asset_exchange_group_new_group;
    }
    const foundAsset = BRS.assets.find((tkn) => tkn.asset === assetId);
    if (foundAsset) {
      foundAsset.groupName = groupName;
    }
    if (!BRS.databaseSupport) {
      successMessageAndReloadSidebar();
      return {
        stop: true,
        hide: true
      };
    }
    dbPut(
      "assets",
      {
        asset: assetId,
        groupName
      },
      function(error2) {
        if (error2) return;
        successMessageAndReloadSidebar();
      }
    );
    return {
      stop: true,
      hide: true
    };
  }
  function formsIssueAsset(data) {
    const description = data.description.trim();
    if (!description) {
      return {
        error: $.t("error_description_required")
      };
    }
    data.description = description;
    if (!/^[a-zA-Z0-9]{1,10}$/.test(data.name)) {
      return {
        error: $.t("error_incorrect_name", { name: "name" })
      };
    }
    if (data.mintable) {
      data.mintable = true;
    }
    try {
      const decimals = Number(data.decimals);
      data.quantityQNT = parseQuantityToQNT(data.quantity, decimals);
      data.decimals = decimals;
    } catch (e) {
      return {
        error: e.message
      };
    }
    delete data.quantity;
    return {
      data
    };
  }
  function formsAssetExchangeChangeGroupName(data) {
    const oldGroupName = data.old_group_name;
    const newGroupName = data.new_group_name;
    if (!newGroupName.match(/^[a-z0-9 ]+$/i)) {
      return {
        error: $.t("error_group_name")
      };
    }
    const itemsToUpdate = [];
    BRS.assets.forEach((asset) => {
      if (!asset.bookmarked) return;
      if (asset.groupName === oldGroupName) {
        asset.groupName = newGroupName;
        itemsToUpdate.push({ asset: asset.asset, groupName: newGroupName });
      }
    });
    if (!BRS.databaseSupport) {
      notify($.t("success_group_name_update"), { type: "success" });
      loadAssetExchangeSidebar();
      return {
        stop: true,
        hide: true
      };
    }
    dbPut("assets", itemsToUpdate, function(error2) {
      if (error2) {
        notify($.t("error_save_db"), { type: "danger" });
        return;
      }
      loadAssetExchangeSidebar();
      notify($.t("success_group_name_update"), { type: "success" });
    });
    return {
      stop: true,
      hide: true
    };
  }
  function showAssetOrderModal(assetId, orderType) {
    let quantityQNT;
    let priceNQT;
    let totalNXT;
    let quantity;
    try {
      quantity = String($("#" + orderType + "_asset_quantity").val());
      quantityQNT = parseQuantityToQNT(quantity, BRS.currentAsset.decimals);
      priceNQT = parsePriceQuantityToPriceNQT(String($("#" + orderType + "_asset_price").val()), BRS.currentAsset.decimals);
      totalNXT = formatOrderTotal(quantityQNT, priceNQT);
    } catch {
      notify("Invalid input.", { type: "danger" });
      return;
    }
    if (priceNQT === "0" || quantityQNT === "0") {
      notify($.t("error_amount_price_required"), { type: "danger" });
      return;
    }
    const priceNQTPerWholeQNT = BigInt(priceNQT) * BigInt(Math.pow(10, BRS.currentAsset.decimals));
    let description;
    let tooltipTitle;
    if (orderType === "buy") {
      description = $.t("buy_order_description", {
        quantity: formatQNTAsQuantity(quantityQNT, BRS.currentAsset.decimals),
        asset_name: $("#asset_name").html().escapeHTML(),
        burst: formatNQTAsAmount(priceNQTPerWholeQNT),
        valueSuffix: BRS.valueSuffix
      });
      tooltipTitle = $.t("buy_order_description_help", {
        burst: formatNQTAsAmount(priceNQTPerWholeQNT),
        total_burst: totalNXT,
        valueSuffix: BRS.valueSuffix
      });
    } else {
      description = $.t("sell_order_description", {
        quantity: formatQNTAsQuantity(quantityQNT, BRS.currentAsset.decimals),
        asset_name: $("#asset_name").html().escapeHTML(),
        burst: formatNQTAsAmount(priceNQTPerWholeQNT),
        valueSuffix: BRS.valueSuffix
      });
      tooltipTitle = $.t("sell_order_description_help", {
        burst: formatNQTAsAmount(priceNQTPerWholeQNT),
        total_burst: totalNXT,
        valueSuffix: BRS.valueSuffix
      });
    }
    $("#asset_order_description").html(description);
    $("#asset_order_total").html(totalNXT + " " + BRS.valueSuffix);
    $("#asset_order_modal_button").text($.t(`${orderType}_asset`));
    if (quantity !== "1") {
      $("#asset_order_total_tooltip").show();
      $("#asset_order_total_tooltip").popover("hide");
      $("#asset_order_total_tooltip").data("content", tooltipTitle);
      $("#asset_order_total_tooltip").popover({
        content: tooltipTitle,
        trigger: "hover"
      });
    } else {
      $("#asset_order_total_tooltip").hide();
    }
    $("#asset_order_type").val(orderType === "buy" ? "placeBidOrder" : "placeAskOrder");
    $("#asset_order_asset").val(assetId);
    $("#asset_order_quantity").val(quantityQNT);
    $("#asset_order_price").val(priceNQT);
    showModal("asset_order");
  }
  function formsOrderAsset(data) {
    const requestType = data.asset_order_type;
    delete data.asset_order_type;
    return {
      requestType,
      successMessage: requestType === "placeBidOrder" ? $.t("success_buyOrderAsset") : $.t("success_sellOrderAsset")
    };
  }
  function sortCachedAssets() {
    BRS.assets.sort((a, b) => {
      const nameA = a.name.toUpperCase();
      const nameB = b.name.toUpperCase();
      if (nameA < nameB) return -1;
      if (nameA > nameB) return 1;
      return 0;
    });
  }
  function populateAssetSelector($target) {
    const $allLists = $target.find(".asset_selector ul");
    for (const list of $allLists) {
      const $list = $(list);
      $list.empty();
      if (!BRS.accountInfo.assetBalances) {
        $list.append(`<li><span class='dropdown-item'>${$.t("no_asset_found")}</span></li>`);
        return;
      }
      sortCachedAssets();
      let listContent = "";
      for (const asset of BRS.assets) {
        const foundAsset = BRS.accountInfo.assetBalances.find((tkn) => tkn.asset === asset.asset);
        if (foundAsset) {
          listContent += `<li><a class='dropdown-item' href='#' data-name='${asset.name}' data-asset='${asset.asset}' data-decimals='${asset.decimals}'>${asset.name} - ${asset.asset}</a></li>`;
        }
      }
      if (!listContent) {
        listContent = `<li><span class='dropdown-item'>${$.t("no_asset_found")}</span></li>`;
      }
      $list.html(listContent);
      $list.on("click", "li a", (e) => {
        e.preventDefault();
        const assetId = $(e.currentTarget).data("asset") ?? "";
        const assetName = $(e.currentTarget).data("name") ?? "?";
        const decimals = $(e.currentTarget).data("decimals") ?? "";
        const $formGroup = $(e.currentTarget).closest(".row");
        fillAssetSelectorDetails(assetId, assetName, decimals, $formGroup);
      });
    }
  }
  function formsMintAsset(data) {
    if (!data.quantity) {
      return {
        error: $.t("error_not_specified", {
          name: getTranslatedFieldName("quantity").toLowerCase()
        }).capitalize()
      };
    }
    try {
      data.quantityQNT = parseQuantityToQNT(data.quantity, Number(data.decimals));
    } catch (e) {
      return {
        error: $.t("error_incorrect_quantity_plus", {
          err: e.message.escapeHTML()
        })
      };
    }
    delete data.quantity;
    delete data.decimals;
    delete data.name_plus_asset;
    return {
      data
    };
  }
  function formsDistributeToAssetHolders(data) {
    if (!data.quantity && !data.amountNXT) {
      return {
        error: $.t("error_not_specified", {
          name: getTranslatedFieldName("quantity_and_or_amount").toLowerCase()
        }).capitalize()
      };
    }
    if (!data.holders_asset) {
      return {
        error: $.t("error_not_specified", {
          name: getTranslatedFieldName("to_holders_of").toLowerCase()
        }).capitalize()
      };
    }
    if (!data.quantityMinimum) {
      data.quantityMinimumQNT = "0";
    } else {
      if (!data.holders_decimals) {
        return {
          error: $.t("error_not_specified", {
            name: getTranslatedFieldName("to_holders_of").toLowerCase()
          }).capitalize()
        };
      }
      try {
        data.quantityMinimumQNT = parseQuantityToQNT(data.quantityMinimum, Number(data.holders_decimals));
      } catch (e) {
        return {
          error: $.t("error_incorrect_quantity_plus", {
            err: e.message.escapeHTML()
          })
        };
      }
    }
    if (!data.asset) {
      data.asset = "0";
      data.quantityQNT = "0";
    } else {
      try {
        data.quantityQNT = parseQuantityToQNT(data.quantity, Number(data.decimals));
      } catch (e) {
        return {
          error: $.t("error_incorrect_quantity_plus", {
            err: e.message.escapeHTML()
          })
        };
      }
    }
    delete data.quantity;
    delete data.decimals;
    delete data.name_plus_asset;
    data.assetToDistribute = data.asset;
    data.asset = data.holders_asset;
    delete data.holders_asset;
    delete data.holders_decimals;
    delete data.quantityMinimum;
    return {
      data
    };
  }
  async function showAssetHoldersModal(asset) {
    if (BRS.fetchingModalData) {
      return;
    }
    BRS.fetchingModalData = true;
    const response = await sendRequest("getAssetAccounts", {
      asset,
      ignoreTreasury: false,
      firstIndex: 0,
      lastIndex: BRS.pageSize
    });
    BRS.fetchingModalData = false;
    if (response.errorCode) {
      $("#asset_holders_modal_table tbody").text($.t("error_asset_not_found"));
      $("#asset_holders_modal").modal("show");
      return;
    }
    if (response.accountAssets.length === 0) {
      $("#asset_holders_modal_table tbody").text("");
      $("#asset_holders_modal").modal("show");
      return;
    }
    const assetDetails = getAssetFromCache(response.accountAssets[0].asset);
    if (!assetDetails) {
      return;
    }
    const treasuryHTML = `&nbsp;<i title="${$.t("treasury_account")}" class="fas fa-briefcase"></i>`;
    let qnt = 0n;
    let rows = "";
    for (const holder of response.accountAssets) {
      rows += `
            <tr>
              <td><a href='#modal=user_info&user=${holder.accountRS}'>${getAccountTitleFromObject(holder, "account")}</a> ${holder.isTreasury ? treasuryHTML : ""}</td>
              <td>${formatQNTAsQuantity(holder.quantityQNT, assetDetails.decimals)}</td>
              <td>${holder.isTreasury ? "/" : calculatePercentage(holder.quantityQNT, assetDetails.quantityCirculatingQNT) + "%"}</td>
            </tr>`;
      if (!holder.isTreasury) {
        qnt += BigInt(holder.quantityQNT);
      }
    }
    if (qnt !== BigInt(assetDetails.quantityCirculatingQNT)) {
      const otherQNT = (BigInt(assetDetails.quantityCirculatingQNT) - qnt).toString();
      rows += `
            <tr>
              <td>${$.t("others")}</td>
              <td>${formatQNTAsQuantity(otherQNT, assetDetails.decimals)}</td>
              <td>${calculatePercentage(otherQNT, assetDetails.quantityCirculatingQNT) + "%"}</td>
            </tr>`;
    }
    $("#asset_holders_modal_table tbody").html(rows);
    showModal("asset_holders");
  }
