  async function userInfoModalSmartcontract() {
    if (!BRS.userInfoModal) return;
    const response = await sendRequest("getAT", {
      at: convertRSAccountToNumeric(BRS.userInfoModal.modalAccount.account)
    });
    if (response.errorCode) {
      $("#user_info_modal_smartcontract_table tbody").empty();
      dataLoadFinished($("#user_info_modal_smartcontract_table"));
      return;
    }
    let rows = "";
    const props = [
      "name",
      "description",
      "creatorRS",
      "minActivation",
      "machineCodeHashId",
      "status",
      "atVersion",
      "creationBlock",
      "machineData",
      "machineCode"
    ];
    for (const row of props) {
      const key = row.replace(/\s+/g, "").replace(/([A-Z])/g, function($1) {
        return "_" + $1.toLowerCase();
      });
      rows += "<tr>";
      rows += `<td>${$.t(key)}</td>`;
      let codeHTML = "";
      switch (row) {
        case "minActivation":
          codeHTML = formatNQTAsAmount(response[row]) + " " + BRS.valueSuffix;
          break;
        case "creatorRS":
          codeHTML = getAccountTitle(response[row]);
          break;
        case "machineCode":
          codeHTML = response[row].replace(/0+$/, "");
          break;
        case "status":
          for (const val of ["running", "stopped", "finished", "frozen", "dead"]) {
            if (response[val] === true) {
              codeHTML += (codeHTML === "" ? "" : " + ") + $.t(val);
            }
          }
          break;
        default:
          codeHTML = response[row];
      }
      rows += `<td style='word-break: break-word;'>${codeHTML}</td>`;
      rows += "</tr>";
    }
    $("#user_info_modal_smartcontract_table tbody").html(rows);
    dataLoadFinished($("#user_info_modal_smartcontract_table"));
  }
  async function userInfoModalAssets() {
    if (!BRS.userInfoModal) return;
    const accountInfo = BRS.userInfoModal.modalAccount;
    const response = await sendRequest("getAssetsByIssuer", {
      account: accountInfo.account
    });
    if (response.assets && response.assets.length) {
      for (const issuedAsset of response.assets) {
        cacheAsset(issuedAsset);
      }
    }
    if (!accountInfo.assetBalances) {
      userInfoModalAssetsLoaded();
      return;
    }
    const assetDetailsPromises = accountInfo.assetBalances.filter((currAssetBalance) => currAssetBalance.balanceQNT !== "0").map((currAssetBalance) => getAssetDetails(currAssetBalance.asset));
    await Promise.all(assetDetailsPromises);
    userInfoModalAssetsLoaded();
  }
  function userInfoModalAssetsLoaded() {
    if (!BRS.userInfoModal) {
      return;
    }
    const accountInfo = BRS.userInfoModal.modalAccount;
    const assetBalances = accountInfo.assetBalances || [];
    const currentAccount = accountInfo.account;
    const combinedAssets = [];
    for (const balance of assetBalances) {
      if (balance.balanceQNT === "0") {
        continue;
      }
      const cachedAsset = BRS.assets.find((asset) => asset.asset === balance.asset);
      if (cachedAsset) {
        combinedAssets.push({
          ...cachedAsset,
          balanceQNT: balance.balanceQNT
        });
      }
    }
    for (const cachedAsset of BRS.assets) {
      if (cachedAsset.account !== currentAccount) {
        continue;
      }
      const isAlreadyIncluded = combinedAssets.some((asset) => asset.asset === cachedAsset.asset);
      if (!isAlreadyIncluded) {
        combinedAssets.push({
          ...cachedAsset,
          balanceQNT: "0"
        });
      }
    }
    combinedAssets.sort((a, b) => {
      const aIsIssued = a.account === currentAccount;
      const bIsIssued = b.account === currentAccount;
      if (aIsIssued && !bIsIssued) return -1;
      if (!aIsIssued && bIsIssued) return 1;
      return a.name.localeCompare(b.name);
    });
    let rows = "";
    for (const asset of combinedAssets) {
      const percentageAsset = calculatePercentage(asset.balanceQNT, asset.quantityCirculatingQNT);
      const isIssued = asset.account === currentAccount;
      const assetName = asset.name;
      const assetId = asset.asset;
      rows += `
            <tr>
              <td>
                <a href='#page=asset_exchange&subPage=${assetId}'
                   ${isIssued ? " style='font-weight:bold'" : ""}>
                   ${assetName}
                </a>
              </td>
              <td class='quantity'>${formatQNTAsQuantity(asset.balanceQNT, asset.decimals)}</td>
              <td>${formatQNTAsQuantity(asset.quantityCirculatingQNT, asset.decimals)}</td>
              <td>${percentageAsset}%</td>
            </tr>`;
    }
    $("#user_info_modal_assets_table tbody").empty().append(rows);
    dataLoadFinished($("#user_info_modal_assets_table"));
  }

  // src/js/brs/modals/contacts.ts
  function formsAddContact(data) {
    const error2 = checkContactDataError(data);
    if (error2) {
      return { error: error2 };
    }
    if (data.account_id.charAt(0) === "@") {
      if (data.converted_account_id) {
        data.account_id = data.converted_account_id;
      } else {
        return {
          error: $.t("error_account_id")
        };
      }
    }
    const address = new NxtAddress(data.account_id);
    if (address.isOk()) {
      data.account = address.getAccountId();
      data.accountRS = address.getAccountRS(BRS.prefix);
    } else {
      return {
        error: $.t("error_account_id")
      };
    }
    for (const Contact in BRS.contacts) {
      if (BRS.contacts[Contact].accountRS === data.accountRS) {
        return { error: $.t("error_contact_account_id_exists") };
      }
      if (BRS.contacts[Contact].name === data.name) {
        return { error: $.t("error_contact_name_exists") };
      }
    }
    saveContactToDatabase(data, $.t("success_contact_add"));
    return { stop: true, hide: true };
  }
  function formsUpdateContact(data) {
    const error2 = checkContactDataError(data);
    if (error2) {
      return { error: error2 };
    }
    if (data.account_id.charAt(0) === "@") {
      if (data.converted_account_id) {
        data.account_id = data.converted_account_id;
      } else {
        return {
          error: $.t("error_account_id")
        };
      }
    }
    if (!data.account_id) {
      return {
        error: $.t("error_contact")
      };
    }
    const address = new NxtAddress(data.account_id);
    if (address.isOk()) {
      data.account = address.getAccountId();
      data.accountRS = address.getAccountRS(BRS.prefix);
    } else {
      return {
        error: $.t("error_account_id")
      };
    }
    saveContactToDatabase(data, $.t("success_contact_update"));
    return { stop: true, hide: true };
  }
  function formsDeleteContact() {
    const accountRs = $("#delete_contact_account_rs").text();
    if (!accountRs || !BRS.contacts[String(accountRs)]) {
      return { error: $.t("error_save_db") };
    }
    delete BRS.contacts[String(accountRs)];
    if (!BRS.databaseSupport) {
      notifyContactOperationSuccess($.t("success_contact_delete"));
      return;
    }
    removeContactFromDB(accountRs);
    return { stop: true, hide: true };
  }
  function showUpdateContactModal(account) {
    let contact = getContactByName(account);
    if (!contact) {
      contact = BRS.contacts[account];
    }
    if (!contact) {
      contact = BRS.contacts[convertNumericToRSAccountFormat(account)];
    }
    if (!contact) {
      notify($.t("error_contact"), { type: "danger" });
      return;
    }
    $("#update_contact_name").val(contact.name);
    $("#update_contact_email").val(contact.email);
    $("#update_contact_account_id").val(contact.accountRS).trigger("blur");
    $("#update_contact_description").val(contact.description);
    showModal("update_contact");
  }
  function showDeleteContactModal(account) {
    let contact = getContactByName(account);
    if (!contact) {
      contact = BRS.contacts[account];
    }
    if (!contact) {
      contact = BRS.contacts[convertNumericToRSAccountFormat(account)];
    }
    if (!contact) {
      notify($.t("error_contact"), { type: "danger" });
      return;
    }
    $("#delete_contact_name").text(contact.name);
    $("#delete_contact_account_rs").text(contact.accountRS);
    $("#delete_contact_account_id").text(contact.account);
    showModal("delete_contact");
  }
  function checkContactDataError(data) {
    if (!data.name) {
      return $.t("error_contact_name_required");
    }
    if (!data.account_id) {
      return $.t("error_account_id_required");
    }
    if (BRS.idRegEx.test(data.name) || BRS.rsRegEx.test(data.name)) {
      return $.t("error_contact_name_alpha");
    }
    if (data.email && !/@/.test(data.email)) {
      return $.t("error_email_address");
    }
  }
  function showAddContactModal(account) {
    $("#add_contact_account_id").val(account).trigger("blur");
    showModal("add_contact");
  }

  // src/js/brs/pages/messages.ts
  async function pagesMessages() {
    if (BRS.currentPage === "messages" && BRS.currentSubPage) {
      const chatMessages = buildChatMessages(BRS.currentSubPage);
      $("#message_details").html(chatMessages);
      $("#message_details").scrollTop($("#message_details")[0].scrollHeight);
      pageLoaded();
      return;
    }
    $("#messages_vtab").empty();
    $("#no_message_selected").show();
    $("#no_messages_available").hide();
    $("#messages_card").hide();
    BRS._messages = {};
    const response = await sendRequest("getAccountTransactions+", {
      account: BRS.account,
      firstIndex: 0,
      lastIndex: 74,
      type: 1,
      subtype: 0,
      includeIndirect: false
    });
    if (response.transactions && response.transactions.length) {
      for (const tx of response.transactions) {
        const otherUser = tx.recipient === BRS.account ? tx.sender : tx.recipient;
        if (!(otherUser in BRS._messages)) {
          BRS._messages[otherUser] = [];
        }
        BRS._messages[otherUser].push(tx);
      }
      displayMessageSidebar();
    } else {
      $("#no_message_selected").hide();
      $("#no_messages_available").show();
    }
    pageLoaded();
  }
  function displayMessageSidebar() {
    let rows = "";
    const sidebarUserList = [];
    for (const otherUser in BRS._messages) {
      BRS._messages[otherUser].sort((a, b) => a.timestamp - b.timestamp);
      const otherUserRS = otherUser === BRS._messages[otherUser][0].sender ? BRS._messages[otherUser][0].senderRS : BRS._messages[otherUser][0].recipientRS;
      sidebarUserList.push({
        timestamp: BRS._messages[otherUser][BRS._messages[otherUser].length - 1].timestamp,
        user: otherUser,
        userRS: otherUserRS
      });
    }
    sidebarUserList.sort((a, b) => a.timestamp - b.timestamp);
    for (const sidebarUser of sidebarUserList) {
      let classContact = "list-group-no-contact";
      if (sidebarUser.userRS in BRS.contacts) {
        classContact = "list-group-is-contact";
      }
      rows += `
            <a href='#page=messages&subPage=${sidebarUser.userRS}'
              class='nav-link ${classContact}' 
              data-item="${sidebarUser.user}"
              data-context="messages_vtab_context"
              >
              ${getAccountTitleFromObject(sidebarUser, "user")}
              <br>
              <small>${formatTimestampAsDateTime(sidebarUser.timestamp)}</small>
            </a>`;
    }
    $("#messages_vtab").empty().append(rows);
    if (BRS.currentSubPage) {
      $("#messages_vtab a[data-item=" + BRS.currentSubPage + "]").addClass("active");
    }
  }
  function checkIncomingMessages(transactions) {
    if (!BRS.checkIncoming.newTransactions && !BRS.checkIncoming.unconfirmedChanged) {
      return;
    }
    let reloadContent = false;
    let reloadSidebar = false;
    const newUnconfMessages = transactions.filter((tx) => tx.type === 1 && tx.subtype === 0 && tx.height === UNCONFIRMED_HEIGHT);
    if (newUnconfMessages.length > 0) {
      reloadContent = true;
    }
    const newMessagesTransactions = transactions.filter(
      (tx) => tx.type === 1 && tx.subtype === 0 && tx.height !== UNCONFIRMED_HEIGHT && (tx.sender === BRS.account || tx.recipient === BRS.account)
    );
    for (const trans of newMessagesTransactions) {
      const chatTo = trans.sender === BRS.account ? trans.recipient : trans.sender;
      if (BRS._messages[chatTo] === void 0) {
        reloadSidebar = true;
        BRS._messages[chatTo] = [trans];
      } else {
        if (BRS._messages[chatTo].find((tx) => tx.transaction === trans.transaction)) {
          continue;
        }
        BRS._messages[chatTo].push(trans);
        BRS._messages[chatTo].sort(function(a, b) {
          return a.timestamp - b.timestamp;
        });
        reloadContent = true;
      }
      if (trans.sender !== BRS.account) {
        notify(
          $.t("you_received_message", {
            account: getAccountRSFromObject(trans, "sender"),
            name: getAccountTitleFromObject(trans, "sender")
          }),
          { type: "success" }
        );
      }
    }
    if (BRS.currentPage === "messages") {
      if (reloadSidebar) {
        displayMessageSidebar();
      }
      if (reloadContent) {
        reloadCurrentPage();
      }
    }
  }
  function buildChatMessages(account_id) {
    const msgFromTemplate = `
        <div class="direct-chat-msg %pendingClass%">
            <div class="direct-chat-infos clearfix">
                <span class="direct-chat-name float-left">%from%</span>
                <span class="direct-chat-timestamp float-right">%timestamp%</span>
            </div>
            <img class="direct-chat-img" src="%imgsrc%">
            <div class="direct-chat-text">%message%</div>
        </div>`;
    const msgToTemplate = `
        <div class="direct-chat-msg right %pendingClass%">
            <div class="direct-chat-infos clearfix">
                <span class="direct-chat-name float-right">%from%</span>
                <span class="direct-chat-timestamp float-left">%timestamp%</span>
            </div>
            <img class="direct-chat-img" src="%imgsrc%">
            <div class="direct-chat-text">%message%</div>
        </div>`;
    let output2 = "";
    const messages2 = BRS._messages[account_id].slice(0);
    const unconfirmedTransactions = getUnconfirmedTransactionsFromCache(1, 0, {
      recipient: account_id,
      sender: account_id
    });
    if (unconfirmedTransactions) {
      messages2.push(...unconfirmedTransactions.reverse());
    }
    for (const message of messages2) {
      const containerID = "message" + message.transaction;
      const plainMessage = getMessageTextFromTX(message);
      let messageField = $.t("message_empty");
      if (plainMessage) {
        messageField = plainMessage.escapeHTML().nl2br();
      }
      const secretMessage = getEncryptedMessageFromTX(message);
      if (!plainMessage && secretMessage) {
        if (secretMessage.isDecrypted) {
          messageField = '<i class="fas fa-lock"></i> ' + secretMessage.message.escapeHTML().nl2br();
        } else {
          const passphrase = getDecryptionPassword();
          if (passphrase) {
            messageField = `<i class="fas fa-lock"></i> <span id="${containerID}">${BRS.pendingTransactionHTML}</span>`;
            setTimeout(decryptAttachmentFieldAndUpdateSelector, 10, message, "encryptedMessage", passphrase, containerID);
          } else {
            messageField = `<i class='fas fa-exclamation-triangle'></i> <a href="#modal=messages_decrypt" class="btn btn-warning"><i class="fas fa-key"></i></a>`;
          }
        }
      }
      const day = formatTimestampAsDateTime(message.timestamp);
      let pendingClass = "";
      if (message.height === UNCONFIRMED_HEIGHT) {
        pendingClass = "messagePending";
      }
      if (message.sender === BRS.account) {
        output2 += msgToTemplate.replace("%pendingClass%", pendingClass).replace("%from%", $.t("you")).replace("%timestamp%", day).replace("%imgsrc%", (0, import_hashicon.default)(message.sender, { size: 40 }).toDataURL()).replace("%message%", messageField);
      } else {
        output2 += msgFromTemplate.replace("%pendingClass%", pendingClass).replace("%from%", message.senderRS).replace("%timestamp%", day).replace("%imgsrc%", (0, import_hashicon.default)(message.sender, { size: 40 }).toDataURL()).replace("%message%", messageField);
      }
    }
    return output2;
  }
  function loadMessagesSubPage(userRS) {
    $("#messages_vtab a.active").removeClass("active");
    if (!userRS) return;
    const userID = convertRSAccountToNumeric(userRS);
    if (!userID) return;
    const element = $("#messages_vtab a[data-item=" + userID + "]");
    if (!element.length) {
      console.log("Invalid user");
      return;
    }
    element.addClass("active");
    BRS.currentSubPage = convertRSAccountToNumeric(userRS);
    const contactName = BRS.contacts[userRS]?.name;
    const rsAddress = userRS;
    const friendlyName = contactName ?? rsAddress;
    $("#chatbox_title").text(friendlyName);
    $("#no_message_selected, #no_messages_available").hide();
    $("#messages_card").hide();
    const chatMessages = buildChatMessages(BRS.currentSubPage);
    $("#message_details").html(chatMessages);
    $("#messages_card").show();
    $("#message_details").scrollTop($("#message_details")[0].scrollHeight);
    window.scrollTo({
      top: 0,
      behavior: "smooth"
    });
  }
  function messagesVtabContextHandler(option, account) {
    if (option === "add_contact") {
      showAddContactModal(account);
    } else if (option === "update_contact") {
      showUpdateContactModal(account);
    } else if (option === "send_burst") {
      showSendMoneyModal(account, "");
    } else if (option === "account_info") {
      showAccountModal(account);
    }
  }

  // src/js/brs/pages/mining.forged_blocks.ts
  async function pagesForgedBlocks() {
    const response = await sendRequest("getAccountBlocks+", {
      account: BRS.account,
      firstIndex: BRS.pageSize * (BRS.pageNumber - 1),
      lastIndex: BRS.pageSize * BRS.pageNumber,
      timestamp: 0
    });
    if (!response.blocks || response.blocks.length === 0) {
      drawBlocksInCurrentPage([]);
      return;
    }
    if (response.blocks.length > BRS.pageSize) {
      BRS.hasMorePages = true;
      response.blocks.pop();
    }
    drawBlocksInCurrentPage(response.blocks);
  }

  // src/js/brs/pages/notifications.ts
  function pagesNotifications() {
    const notes = getNotifications(BRS.pageSize * (BRS.pageNumber - 1), BRS.pageSize * BRS.pageNumber);
    if (!notes.length) {
      dataLoaded("");
    }
    if (notes.length > BRS.pageSize) {
      BRS.hasMorePages = true;
      notes.pop();
    }
    let rows = "";
    for (const note of notes) {
      const date = new Date(note.timestamp);
      rows += `
            <tr>
              <td>${date.toLocaleString(BRS.settings.language)}</td>
              <td>${$.t(note.type)}</td>
              <td>${note.message}</td>
            </tr>`;
    }
    dataLoaded(rows);
  }

