  async function pagesSearchResults() {
    async function requestAccountAndShow(accountValue) {
      const response = await sendRequest("getAccount", {
        account: accountValue,
        getCommittedAmount: "true"
      });
      if (response.errorCode) {
        dataLoaded($.t("error_search_no_results"));
        return;
      }
      showAccountModal(response);
      showAccountSearchResults([response.account]);
    }
    const userInput = $("#search_box input").val().trim();
    let searchText = userInput;
    if (searchText.startsWith("-")) {
      try {
        searchText = (BigInt(userInput) + (1n << 64n)).toString(10);
      } catch {
        searchText = userInput;
      }
    }
    if (BRS.rsRegEx.test(searchText)) {
      requestAccountAndShow(searchText);
      return;
    }
    if (BRS.idRegEx.test(searchText)) {
      const response = await sendRequest("getTransaction", {
        transaction: searchText
      });
      if (response.errorCode) {
        dataLoaded($.t("no_transactions_found"));
        return;
      }
      showTransactionModal(response);
      const htmlResult = `
                <strong>${$.t("transaction")}:</strong>
                <ul>
                  <li><a href="#modal=transaction_info&transaction=${response.transaction}">${response.transaction}</a></li>
                </ul>`;
      dataLoaded(htmlResult);
      return;
    }
    const splitted = searchText.split(":");
    if (splitted.length !== 2) {
      dataLoaded("");
      return;
    }
    switch (splitted[0].trim()) {
      case "a":
      case "address":
        requestAccountAndShow(splitted[1].trim());
        return;
      case "b":
      case "block": {
        const response = await sendRequest("getBlock", {
          height: splitted[1].trim(),
          includeTransactions: "true"
        });
        if (response.errorCode) {
          dataLoaded($.t("error_search_no_results"));
          return;
        }
        showBlockInfoModal(response);
        const htmlResult = `
                <strong>${$.t("block")}:</strong>
                <ul>
                  <li><a href="#modal=block_info&block=${response.height}">${response.height}</a></li>
                </ul>`;
        dataLoaded(htmlResult);
        return;
      }
      case "alias": {
        let aliases = [];
        const response = await sendRequest("getAliasesByName", {
          aliasName: splitted[1].trim()
        });
        if (!response.errorCode) {
          aliases = response.aliases;
        }
        if (BRS.tlds[splitted[1].trim()]) {
          const tld = await sendRequest("getAlias", {
            alias: BRS.tlds[splitted[1].trim()]
          });
          if (!tld.errorCode) {
            aliases.push(tld);
          }
        }
        if (aliases.length === 0) {
          dataLoaded($.t("error_search_no_results"));
          return;
        }
        if (aliases.length === 1) {
          showAliasInfoModal(aliases[0]);
        }
        showAliasesSearchResults(aliases);
        return;
      }
      case "name": {
        const response = await sendRequest("getAccountsWithName", {
          name: splitted[1].trim()
        });
        if (response.errorCode || !response.accounts || response.accounts.length === 0) {
          dataLoaded($.t("error_search_no_results"));
          return;
        }
        if (response.accounts.length === 1) {
          requestAccountAndShow(response.accounts[0]);
          return;
        }
        showAccountSearchResults(response.accounts);
        return;
      }
      case "token": {
        const response = await sendRequest("getAssetsByName", {
          name: splitted[1].trim()
        });
        if (response.errorCode || !response.assets || response.assets.length === 0) {
          dataLoaded($.t("error_search_no_results"));
          return;
        }
        showAssetSearchResults(response.assets);
        return;
      }
      default:
        dataLoaded("");
    }
  }

  // src/js/brs/pages/dashboard.ts
  function incomingUpdateDashboardTransactions(newTransactions) {
    if (!newTransactions.length) {
      return;
    }
    let hasConfirmed = false;
    const rows = newTransactions.reduce((prev, currTr) => {
      if (currTr.height !== UNCONFIRMED_HEIGHT) {
        hasConfirmed = true;
      }
      return prev + getTransactionRowDashboardHTML(currTr);
    }, "");
    if (hasConfirmed) {
      $("#dashboard_transactions_table tbody").empty().append(rows);
    } else {
      $("#dashboard_transactions_table tbody tr.tentative").remove();
      $("#dashboard_transactions_table tbody").prepend(rows);
    }
    const $parent = $("#dashboard_transactions_table").parent();
    if ($parent.hasClass("data-empty")) {
      $parent.removeClass("data-empty");
      if ($parent.data("no-padding")) {
        $parent.parent().addClass("no-padding");
      }
    }
  }
  function getTransactionRowDashboardHTML(transaction) {
    const details = getTransactionDetails(transaction);
    let confirmationHTML = String(transaction.confirmations);
    if (transaction.height === UNCONFIRMED_HEIGHT) {
      confirmationHTML = BRS.pendingTransactionHTML;
    } else if (transaction.confirmations > 10) {
      confirmationHTML = "10+";
    }
    const rowClass = transaction.height === UNCONFIRMED_HEIGHT ? "tentative" : "confirmed";
    const messageIcon = details.hasMessage ? " + <i class='far fa-envelope-open'></i>&nbsp;" : "";
    return `
        <tr class='${rowClass}'>
            <td><a href='#modal=transaction_info&transaction=${transaction.transaction}'>${formatTimestampAsDateTime(transaction.timestamp)}</a></td>
            <td>${details.nameOfTransaction}${messageIcon}</td>
            <td>${details.circleText}</td>
            <td ${details.colorClass}>${details.amountToFromViewerHTML}</td>
            <td>${details.accountLink}</td>
            <td class='confirmations'>${confirmationHTML}</td>
        </tr>
    `;
  }
  function updateDashboardBlocks() {
    let rows = "";
    for (const block of BRS.blocks) {
      const isBold = block.numberOfTransactions > 0 ? "style='font-weight:bold'" : "";
      const height = String(block.height);
      const timestamp = String(block.timestamp);
      const formattedTimestamp = formatTimestampAsDateTime(block.timestamp);
      const totalAmount = formatNQTAsAmount(block.totalAmountNQT);
      const totalFee = formatNQTAsAmount(block.totalFeeNQT);
      const transactionCount = formatNumber(block.numberOfTransactions);
      rows += `
            <tr>
              <td>
                <a href='#modal=block_info&block=${height}' ${isBold}>
                  ${height}
                </a>
              </td>
              <td data-timestamp='${timestamp}'>${formattedTimestamp}</td>
              <td>${totalAmount} + ${totalFee}</td>
              <td>${transactionCount}</td>
            </tr>`;
    }
    $("#dashboard_blocks_table tbody").html(rows);
  }
  function updateConfirmationsInDashboardTransactions(numberToAdd) {
    $("#dashboard_transactions_table tr.confirmed td.confirmations").each(function() {
      if ($(this).data("incoming")) {
        $(this).removeData("incoming");
        return;
      }
      const confirmations = parseInt($(this).text(), 10);
      const nrConfirmations = confirmations + numberToAdd;
      if (confirmations <= 10) {
        if (nrConfirmations > 10) {
          $(this).text("10+");
          return;
        }
        $(this).text(nrConfirmations);
        return;
      }
      $(this).text("10+");
    });
  }

  // src/js/brs/core/check_incoming.account.ts
  var import_hashicon2 = __toESM(require_hashicon_umd());
  async function getAndUpdateAccountDetails(firstRun, callback) {
    const response = await sendRequest("getAccount", {
      account: BRS.account,
      getCommittedAmount: "true"
    });
    const previousAccountInfo = BRS.accountInfo;
    BRS.accountInfo = response;
    if (isErrorResponse(response)) {
      $("#account_balance, #account_committed_balance, #account_balance_sendmoney").html("0");
      $("#account_nr_assets").html("0");
      if (response.errorCode === 5) {
        if (BRS.downloadingBlockchain) {
          if (BRS.newlyCreatedAccount) {
            $("#dashboard_message").addClass("alert-success").removeClass("alert-danger").html(
              $.t("status_new_account", {
                extended_address: BRS.accountRSExtended,
                short_address: BRS.accountRS,
                public_key: BRS.publicKey
              }) + "<br /><br />" + $.t("status_blockchain_downloading")
            ).show();
          } else {
            $("#dashboard_message").addClass("alert-success").removeClass("alert-danger").html($.t("status_blockchain_downloading")).show();
          }
        } else if (BRS.rescaningBlockchain) {
          $("#dashboard_message").addClass("alert-danger").removeClass("alert-success").html($.t("status_blockchain_rescanning")).show();
        } else {
          $("#dashboard_message").addClass("alert-success").removeClass("alert-danger").html(
            $.t("status_new_account", {
              extended_address: BRS.accountRSExtended,
              short_address: BRS.accountRS,
              public_key: BRS.publicKey
            })
          ).show();
        }
      } else {
        $("#dashboard_message").addClass("alert-danger").removeClass("alert-success").text(response.errorDescription).show();
      }
    } else {
      if (BRS.accountRS && BRS.accountInfo.accountRS !== BRS.accountRS) {
        notify("Generated Reed Solomon address different from the one in the blockchain!", { type: "danger" });
        BRS.accountRS = BRS.accountInfo.accountRS;
      }
      if (BRS.downloadingBlockchain) {
        $("#dashboard_message").addClass("alert-success").removeClass("alert-danger").html($.t("status_blockchain_downloading")).show();
      } else if (BRS.rescaningBlockchain) {
        $("#dashboard_message").addClass("alert-danger").removeClass("alert-success").html($.t("status_blockchain_rescanning")).show();
      } else if (!BRS.accountInfo.publicKey) {
        $("#dashboard_message").addClass("alert-danger").removeClass("alert-success").html($.t("no_public_key_warning") + " " + $.t("public_key_actions")).show();
      } else {
        $("#dashboard_message").hide();
      }
      const showAssetDifference = !BRS.downloadingBlockchain || BRS.blocks.length > 0 && BRS.blockchainStatus && BRS.blockchainStatus.time - BRS.blocks[0].timestamp < 60 * 60 * 24 * 7;
      if (BRS.databaseSupport) {
        dbGet(
          "data",
          {
            id: "asset_balances_" + BRS.account
          },
          function(_error, asset_balance) {
            if (asset_balance) {
              let previous_balances = asset_balance.contents;
              if (!BRS.accountInfo.assetBalances) {
                BRS.accountInfo.assetBalances = [];
              }
              const current_balances = JSON.stringify(BRS.accountInfo.assetBalances);
              if (previous_balances !== current_balances) {
                if (previous_balances !== "undefined" && typeof previous_balances !== "undefined") {
                  previous_balances = JSON.parse(previous_balances);
                } else {
                  previous_balances = [];
                }
                dbPut("data", {
                  id: "asset_balances_" + BRS.account,
                  contents: current_balances
                });
                if (showAssetDifference) {
                  checkAssetDifferences(BRS.accountInfo.assetBalances, previous_balances);
                }
              }
            } else {
              dbPut("data", {
                id: "asset_balances_" + BRS.account,
                contents: JSON.stringify(BRS.accountInfo.assetBalances)
              });
            }
          }
        );
      } else if (showAssetDifference && previousAccountInfo && previousAccountInfo.assetBalances) {
        const previousBalances = JSON.stringify(previousAccountInfo.assetBalances);
        const currentBalances = JSON.stringify(BRS.accountInfo.assetBalances);
        if (previousBalances !== currentBalances) {
          checkAssetDifferences(BRS.accountInfo.assetBalances || [], previousAccountInfo.assetBalances);
        }
      }
      $("#account_balance, #account_balance_sendmoney").html(formatStyledAmount(response.unconfirmedBalanceNQT));
      $("#account_balance_locked, #account_balance_sendmoney").html(
        formatStyledAmount((BigInt(response.balanceNQT) - BigInt(response.unconfirmedBalanceNQT)).toString(10))
      );
      $("#account_committed_balance, #account_balance_sendmoney").html(formatStyledAmount(response.committedBalanceNQT || ""));
      let nr_assets = 0;
      if (response.assetBalances) {
        for (let i = 0; i < response.assetBalances.length; i++) {
          if (response.assetBalances[i].balanceQNT !== "0") {
            nr_assets++;
          }
        }
      }
      $("#account_nr_assets").html(nr_assets.toString());
      if (response.name) {
        $("#account_name").text(response.name).removeAttr("data-i18n");
      }
    }
    if (firstRun) {
      $("#account_avatar").attr("src", (0, import_hashicon2.default)(BRS.account, { size: 40 }).toDataURL());
      $("#account_balance, #account_committed_balance, #account_nr_assets, #account_balance_sendmoney").removeClass("loading_dots");
    }
    if (callback) {
      callback();
    }
  }
  async function checkAssetDifferences(current_balances, previous_balances) {
    const current_balances_ = {};
    const previous_balances_ = {};
    if (previous_balances.length) {
      for (const k in previous_balances) {
        previous_balances_[previous_balances[k].asset] = previous_balances[k].balanceQNT;
      }
    }
    if (current_balances.length) {
      for (const k in current_balances) {
        current_balances_[current_balances[k].asset] = current_balances[k].balanceQNT;
      }
    }
    const diff = {};
    for (const k in previous_balances_) {
      if (!(k in current_balances_)) {
        diff[k] = "-" + previous_balances_[k];
      } else if (previous_balances_[k] !== current_balances_[k]) {
        const change = (BigInt(current_balances_[k]) - BigInt(previous_balances_[k])).toString(10);
        diff[k] = change;
      }
    }
    for (const k in current_balances_) {
      if (!(k in previous_balances_)) {
        diff[k] = current_balances_[k];
      }
    }
    const nr = Object.keys(diff).length;
    if (nr === 0) {
      return;
    }
    if (nr <= 3) {
      for (const k in diff) {
        const asset = await sendRequest("getAsset", { asset: k });
        if (asset.errorCode) {
          return;
        }
        let difference = diff[k];
        let quantity;
        if (difference.charAt(0) !== "-") {
          quantity = formatQNTAsQuantity(difference, asset.decimals);
          if (quantity !== "0") {
            notify(
              $.t("you_received_assets", {
                asset: asset.asset,
                name: asset.name,
                count: quantity
              }),
              { type: "success" }
            );
          }
        } else {
          difference = difference.substring(1);
          quantity = formatQNTAsQuantity(difference, asset.decimals);
          if (quantity !== "0") {
            notify(
              $.t("you_sold_assets", {
                asset: asset.asset,
                name: asset.name,
                count: quantity
              }),
              { type: "success" }
            );
          }
        }
      }
      return;
    }
    notify($.t("multiple_assets_differences"), { type: "success" });
  }

  // src/js/brs/pages/transactions.ts
  async function pagesTransactions() {
    function getFrom() {
      const from = $("input[name=transactions_from_account]:checked").val();
      if (from === "me") {
        return BRS.account;
      }
      const fromWho = $("#transaction_from_account_account").val().trim();
      if (BRS.rsRegEx.test(fromWho) || BRS.idRegEx.test(fromWho)) {
        return fromWho;
      }
      const foundContact = getContactByName(fromWho);
      if (foundContact) {
        return foundContact.accountRS;
      }
      return "";
    }
    const account = getFrom();
    if (!account) {
      notify($.t("name_not_in_contacts", { name: account }), { type: "danger" });
      return;
    }
    if (BRS.transactionsPageType === "unconfirmed") {
      displayUnconfirmedTransactions(account);
      return;
    }
    let rows = "";
    let unconfirmedTransactions;
    const params = {
      account,
      firstIndex: BRS.pageSize * (BRS.pageNumber - 1),
      lastIndex: BRS.pageSize * BRS.pageNumber,
      includeIndirect: true
    };
    if (BRS.transactionsPageType) {
      const types = BRS.transactionsPageType.split(":");
      params.type = types[0];
      params.subtype = types[1];
      unconfirmedTransactions = getUnconfirmedTransactionsFromCache(Number(params.type), Number(params.subtype));
    } else {
      unconfirmedTransactions = BRS.unconfirmedTransactions;
    }
    if (unconfirmedTransactions && BRS.pageNumber === 1) {
      rows = unconfirmedTransactions.reduce((prev, currTr) => prev + getTransactionRowHTML(currTr, account), "");
    }
    const response = await sendRequest("getAccountTransactions+", params);
    if (response.transactions && response.transactions.length) {
      if (response.transactions.length > BRS.pageSize) {
        BRS.hasMorePages = true;
        response.transactions.pop();
      }
      rows += response.transactions.reduce((prev, currTr) => prev + getTransactionRowHTML(currTr, account), "");
    }
    dataLoaded(rows);
  }
  async function displayUnconfirmedTransactions(viewAccount) {
    const response = await sendRequest("getUnconfirmedTransactions", {});
    let rows = "";
    if (response.unconfirmedTransactions && response.unconfirmedTransactions.length) {
      rows = response.unconfirmedTransactions.reduce(
        (prev, currTr) => prev + getTransactionRowHTML(mapUnconfirmedToTransaction(currTr), viewAccount),
        ""
      );
    }
    dataLoaded(rows);
  }
  function getTransactionRowHTML(transaction, viewAccount) {
    const details = getTransactionDetails(transaction, viewAccount);
    let confirmationHTML = BRS.pendingTransactionHTML;
    if (transaction.height !== UNCONFIRMED_HEIGHT) {
      confirmationHTML = formatNumber(transaction.confirmations);
    }
    const rowClass = transaction.height === UNCONFIRMED_HEIGHT && details.toFromViewer ? " class='tentative'" : "";
    const messageIcon = details.hasMessage ? "<i class='far fa-envelope-open'></i>&nbsp;" : "";
    return `
        <tr ${rowClass}>
          <td><a href='#modal=transaction_info&transaction=${transaction.transaction}'>${transaction.transaction}</a></td>
          <td>${messageIcon}</td>
          <td>${formatTimestampAsDateTime(transaction.timestamp)}</td>
          <td>${details.nameOfTransaction}</td>
          <td>${details.circleText}</td>
          <td ${details.colorClass}>${details.amountToFromViewerHTML}</td>
          <td>${formatNQTAsAmount(transaction.feeNQT)}</td>
          <td>${details.accountLink}</td>
          <td>${confirmationHTML}</td>
        </tr>`;
  }
  function evTransactionsPageTypeClick(e) {
    e.preventDefault();
    const element = e.target;
    const type = $(element).data("type");
    if (!type) {
      BRS.transactionsPageType = "";
    } else if (type === "unconfirmed") {
      BRS.transactionsPageType = "unconfirmed";
    } else {
      BRS.transactionsPageType = type;
    }
    BRS.pageNumber = 1;
    BRS.hasMorePages = false;
    $(element).parents(".btn-group").find(".text").text($(element).text());
    $(".popover").remove();
    reloadCurrentPage();
  }
  function incomingTransactions() {
    if (BRS.pageNumber === 1 && (BRS.transactionsPageType === "unconfirmed" || BRS.transactionsPageType === "")) {
      reloadCurrentPage();
    }
  }

  // src/js/brs/pages/assets.asset_administration.ts
  async function pagesAssestAdministration() {
    const myIssuedAssets = [];
    const issuedAssets = await sendRequest("getAssetsByOwner+", { account: BRS.account });
    if (issuedAssets.errorCode || issuedAssets.assets.length === 0) {
      dataLoaded();
    }
    for (const myAsset of issuedAssets.assets) {
      const foundAsset = BRS.accountInfo.assetBalances?.find((asset) => asset.asset === myAsset.asset);
      if (foundAsset) {
        myIssuedAssets.push({ balanceQNT: foundAsset.balanceQNT, ...myAsset });
      } else {
        myIssuedAssets.push({ balanceQNT: "0", ...myAsset });
      }
    }
    myIssuedAssets.sort((a, b) => a.name.toLowerCase().localeCompare(b.name.toLowerCase()));
    let rows = "";
    for (const asset of myIssuedAssets) {
      let mintHTML = `
            <a href='#modal=mint_asset&asset=${asset.asset}&name=${asset.name}&decimals=${String(asset.decimals)}'>
                ${$.t("yes")}
            </a>`;
      const unconfirmedMintTx = getUnconfirmedTransactionsFromCache(2, 6, {
        attachment: { asset: asset.asset }
      });
      if (unconfirmedMintTx) {
        mintHTML = BRS.pendingTransactionHTML;
      }
      let distributionHTML = `
            <a href='#modal=distribute_to_asset_holders&asset=${asset.asset}&name=${asset.name}&decimals=${String(asset.decimals)}'>
                <i class="fa fa-magic" aria-hidden="true"></i>
            </a>`;
      const unconfirmedDistributionTx = getUnconfirmedTransactionsFromCache(2, 8, {
        attachment: { asset: asset.asset }
      });
      if (unconfirmedDistributionTx) {
        distributionHTML = BRS.pendingTransactionHTML;
      }
      let transferHTML = `
            <a href='#modal=transfer_asset_ownership&asset=${asset.asset}'>
                <i class="fa fa-magic" aria-hidden="true"></i>
            </a>`;
      const unconfirmedTransferTx = getUnconfirmedTransactionsFromCache(2, 10, {
        sender: BRS.account
      });
      if (unconfirmedTransferTx) {
        transferHTML = BRS.pendingTransactionHTML;
      }
      let treasuryHTML = `
            <a href='#modal=add_asset_treasury_account&asset=${asset.asset}'>
                <i class="fa fa-magic" aria-hidden="true"></i>
            </a>`;
      const unconfirmedTreasuryTx = getUnconfirmedTransactionsFromCache(2, 7, {
        sender: BRS.account
      });
      if (unconfirmedTreasuryTx) {
        treasuryHTML = BRS.pendingTransactionHTML;
      }
      rows += `
            <tr data-asset="${asset.asset}">
              <td><a href='#page=asset_exchange&subPage=${asset.asset}'>
                ${asset.name}</a>
              </td>
              <td>${asset.asset}</td>
              <td class="quantity">${formatQNTAsQuantity(asset.balanceQNT, asset.decimals)}</td>
              <td>${formatQNTAsQuantity(asset.quantityCirculatingQNT, asset.decimals)}</td>
              <td>${asset.mintable ? mintHTML : $.t("no")}</i></td>
              <td>${distributionHTML}</td>
              <td>${transferHTML}</td>
              <td>${treasuryHTML}</td>
            </tr>`;
    }
    dataLoaded(rows);
  }
  function incomingAssetAdministration() {
    if (BRS.checkIncoming.newBlock || BRS.checkIncoming.unconfirmedChanged) {
      reloadCurrentPage();
    }
  }

  // src/js/brs/core/check_incoming.ts
  function setCheckIncomingInterval(seconds) {
    if (seconds === BRS.stateIntervalSeconds && BRS.stateInterval) {
      return;
    }
    if (BRS.stateInterval) {
      clearInterval(BRS.stateInterval);
    }
    BRS.stateIntervalSeconds = seconds;
    BRS.stateInterval = setInterval(checkIncomingBlocksAndTransactions, 1e3 * seconds);
  }
  function checkIncomingNow() {
    if (!BRS.stateInterval) {
      checkIncomingBlocksAndTransactions();
      return;
    }
    clearInterval(BRS.stateInterval);
    checkIncomingBlocksAndTransactions();
    BRS.stateInterval = setInterval(checkIncomingBlocksAndTransactions, 1e3 * BRS.stateIntervalSeconds);
  }
  async function checkIncomingBlocksAndTransactions() {
    BRS.checkIncoming.newBlock = false;
    BRS.checkIncoming.newTransactions = false;
    BRS.checkIncoming.unconfirmedChanged = false;
    BRS.checkIncoming.forceDashboardUpdate = true;
    const response = await sendRequest("getBlockchainStatus", {});
    if (response.errorCode) {
      notify($.t("could_not_connect_to", { server: BRS.server }));
      return;
    }
    const previousLastBlock = BRS.blockchainStatus?.lastBlock || "0";
    BRS.blockchainStatus = response;
    if (previousLastBlock !== BRS.blockchainStatus.lastBlock) {
      BRS.checkIncoming.newBlock = true;
      handleNewBlocks();
      getAndUpdateAccountDetails(false, cacheUserAssets);
      getNewTransactions();
      return;
    }
    addUnconfirmedAndHandleIncoming([]);
    saveCachedAssets();
  }
  function handleNewBlocks() {
    sendRequest("getBlocks", {
      firstIndex: 0,
      lastIndex: 10
    }).then((response) => {
      if (response.errorCode) {
        return;
      }
      if (!BRS.blocks || BRS.blocks.length === 0) {
        BRS.blocks = response.blocks;
      }
      const blockheightDiff = response.blocks[0].height - BRS.blocks[0].height;
      BRS.blocks = response.blocks;
      checkSyncProcess();
      updateDashboardBlocks();
      updateConfirmationsInDashboardTransactions(blockheightDiff);
    });
  }
  function checkSyncProcess() {
    if (!BRS.blockchainStatus) return;
    const secondsBehind = BRS.blockchainStatus.time - BRS.blocks[0].timestamp;
    if (secondsBehind > 60 * 60 * 24 * 4) {
      setCheckIncomingInterval(30);
      BRS.downloadingBlockchain = true;
      $("#downloading_blockchain").show();
      let percentage = 0;
      if (BRS.blockchainStatus.lastBlockchainFeederHeight) {
        percentage = Math.trunc(BRS.blockchainStatus.numberOfBlocks / BRS.blockchainStatus.lastBlockchainFeederHeight * 100);
      }
      $("#downloading_blockchain .progress-bar").css("width", percentage + "%");
      return;
    }
    BRS.downloadingBlockchain = false;
    $("#downloading_blockchain").hide();
    if (secondsBehind > 60 * 60) {
      setCheckIncomingInterval(10);
      BRS.rescaningBlockchain = true;
      return;
    }
    setCheckIncomingInterval(30);
    BRS.rescaningBlockchain = false;
    const onAFork = BRS.blocks.every((block) => block.generator === BRS.blocks[0].generator);
    if (onAFork) {
      notify($.t("fork_warning"), { type: "danger" });
    }
  }
  function getInitialTransactions() {
    BRS.checkIncoming.forceDashboardUpdate = true;
    getNewTransactions();
  }
  function getNewTransactions() {
    sendRequest("getAccountTransactions", {
      account: BRS.account,
      timestamp: (BRS.blocks[0]?.timestamp ?? 0) + 1,
      firstIndex: 0,
      lastIndex: 9,
      includeIndirect: true
    }).then((response) => {
      if (response.transactions && response.transactions.length) {
        BRS.checkIncoming.newTransactions = true;
        BRS.checkIncoming.latestsTransactionsIds = response.transactions.map((tr) => tr.transaction).join();
        addUnconfirmedAndHandleIncoming(response.transactions);
        return;
      }
      addUnconfirmedAndHandleIncoming([]);
    });
  }
  function mapUnconfirmedToTransaction(unconfirmed) {
    return {
      ...unconfirmed,
      confirmations: -1,
      block: "",
      blockTimestamp: -1
    };
  }
  function addUnconfirmedAndHandleIncoming(confirmedTransactions) {
    sendRequest("getUnconfirmedTransactions", {
      account: BRS.account,
      includeIndirect: true
    }).then((response) => {
      const sortedTransactions = response.unconfirmedTransactions?.sort((x, y) => y.timestamp - x.timestamp) || [];
      const transactionIdString = sortedTransactions.map((t2) => t2.transaction).join();
      const ConfUnconfTransactions = sortedTransactions.map(mapUnconfirmedToTransaction);
      BRS.checkIncoming.unconfirmedChanged = transactionIdString !== BRS.checkIncoming.unconfirmedTransactionIds;
      BRS.unconfirmedTransactions = ConfUnconfTransactions;
      BRS.checkIncoming.unconfirmedTransactionIds = transactionIdString;
      handleIncomingTransactions(confirmedTransactions.concat(ConfUnconfTransactions));
    });
  }
  var incomingFunctions = {
    aliases: incomingAliases,
    asset_exchange: incomingAssetExchange,
    block_info: incomingBlockInfo,
    escrow: incomingEscrow,
    latest_blocks: incomingLatestBlocks,
    asset_administration: incomingAssetAdministration,
    my_assets: incomingMyAssets,
    open_orders: incomingOpenOrders,
    peers: incomingPeers,
    subscription: incomingSubscription,
    transactions: incomingTransactions,
    transfer_history: incomingTransferHistory
  };
  function handleIncomingTransactions(transactions) {
    transactions.sort((x, y) => y.timestamp - x.timestamp);
    if (transactions.some((tx) => tx.recipient === BRS.account && tx.confirmations === 0)) {
      notify($.t("new_received_transaction"));
    }
    if (transactions.some((tx) => tx.sender === BRS.account && tx.confirmations === 0)) {
      notify($.t("new_sent_transaction"));
    }
    if (transactions.some((tx) => tx.recipient === BRS.account && tx.confirmations === -1)) {
      notify($.t("pending_received_transaction"));
    }
    if (transactions.some((tx) => tx.sender === BRS.account && tx.confirmations === -1)) {
      notify($.t("pending_sent_transaction"));
    }
    if (BRS.checkIncoming.forceDashboardUpdate || BRS.checkIncoming.newTransactions || BRS.checkIncoming.unconfirmedChanged) {
      incomingUpdateDashboardTransactions(transactions);
    }
    if (BRS.checkIncoming.newBlock || BRS.checkIncoming.unconfirmedChanged) {
      if (incomingFunctions[BRS.currentPage]) {
        incomingFunctions[BRS.currentPage](transactions);
      }
      checkIncomingMessages(transactions);
    }
  }

  // src/js/brs/modals/account_info.ts
  function formsSetAccountInfoComplete(response, inputFormData) {
    const name = inputFormData.name;
    if (name) {
      $("#account_name").html(BRS.pendingTransactionHTML + " " + name).removeAttr("data-i18n");
    } else {
      $("#account_name").text($.t("no_name_set")).attr("data-i18n", "no_name_set");
    }
  }

