  // src/js/brs/modals/escrow.ts
  async function showEscrowDecisionModal(escrow) {
    if (BRS.fetchingModalData) {
      return;
    }
    if (typeof escrow === "object") {
      processEscrowDecisionModalData(escrow);
      return;
    }
    BRS.fetchingModalData = true;
    const response = await sendRequest("getEscrowTransaction", {
      escrow
    });
    BRS.fetchingModalData = false;
    processEscrowDecisionModalData(response);
  }
  function processEscrowDecisionModalData(escrow) {
    $("#escrow_decision_escrow").val(escrow.id);
    $("#escrow_decision_escrow_info").val(escrow.id);
    let decisions = "";
    for (let i = 0; i < escrow.signers.length; i++) {
      decisions += getAccountTitleFromObject(escrow.signers[i], "id") + ": " + $.t(escrow.signers[i].decision) + "<br />";
    }
    $("#escrow_decision_decisions").html(decisions);
    $("#escrow_decision_required").text($.t("number_of_required_signers") + ": " + escrow.requiredSigners);
    $("#escrow_decision_deadline").text(
      $.t("escrow_deadline_action") + ": " + $.t(escrow.deadlineAction) + " -- " + formatTimestampAsDateTime(escrow.deadline)
    );
    showModal("escrow_decision");
  }

  // src/js/brs/core/activate_account.ts
  function activateAccount() {
    if (!BRS.accountInfo.errorCode) {
      notify($.t("recipient_public_key_already_announced"), { type: "success" });
      return;
    }
    let url = "https://activator.signum.network/api/activate";
    if (BRS.isTestNet) {
      url = "https://activator.testnet.signum.network/api/activate";
    }
    const data = {
      account: BRS.accountRS,
      publickey: BRS.publicKey,
      ref: "neoclassic-wallet"
    };
    $.ajax({
      url,
      type: "POST",
      contentType: "application/json",
      data: JSON.stringify(data),
      success: function(response, status, xhr) {
        if (xhr.status === 204) {
          notify($.t("success_activation"), { type: "success" });
          checkIncomingNow();
          return;
        }
        notify($.t("success") + ": " + response, { type: "success" });
      },
      error: function(xhr, status, error2) {
        if (xhr.status === 400) {
          notify($.t("activation_already_done"), { type: "warning" });
        } else if (xhr.status === 429) {
          notify($.t("error_activation_rate_limit"), { type: "danger" });
        } else {
          notify($.t("error_activation_unknown"));
          console.error("Signum activation service returned status: " + xhr.status + " error: " + error2);
        }
      }
    });
  }

