  function modalRouter(params) {
    const modalName = params.get("modal") ?? "";
    const config = MODAL_CONFIG[modalName];
    if (!config) {
      console.log(`Unknown modal "${modalName}".`);
      window.location.hash = "#";
      return;
    }
    for (const param of config.requiredParams ?? []) {
      if (!params.has(param)) {
        console.log(`Missing or invalid ${param} for modal "${modalName}".`);
        window.location.hash = "#";
        return;
      }
    }
    config.handler(params);
  }
  function actionRouter(params) {
    const action = params.get("action");
    if (action === "activate") {
      activateAccount();
      return;
    }
    console.log("Unknow action " + action);
    window.location.hash = "#";
  }
  function checkMinimumFee(value) {
    return isNaN(value) ? BRS.minimumFeeNumber : value < BRS.minimumFeeNumber ? BRS.minimumFeeNumber : value;
  }

  // src/js/brs/core/lockscreen.ts
  function checkSelectedNode() {
    const preferedNode = $("#prefered_node").val();
    if (preferedNode !== BRS.server) {
      BRS.server = preferedNode;
      BRS.currentPage = "lockscreen";
      BRS.currentSubPage = preferedNode;
      BRS.blocks = [];
      BRS.blockchainStatus = void 0;
      $("#node_alert").show();
      $("#node_alert").html(BRS.server);
      $("#brs_version, #brs_version_dashboard").html(BRS.loadingDotsHTML).addClass("loading_dots");
      $("#prefered_node").addClass("is-invalid");
      sendRequest("getConstants+", {}).then((response) => {
        if (response.errorCode) {
          return;
        }
        if (response.networkName.includes("TESTNET")) {
          BRS.isTestNet = true;
          $(".testnet_only, #testnet_login, #testnet_warning").show();
          $(".testnet_only").show();
        } else {
          BRS.isTestNet = false;
          $(".testnet_only, #testnet_login, #testnet_warning").hide();
          $(".testnet_only").hide();
        }
        BRS.prefix = response.addressPrefix + "-";
        BRS.valueSuffix = response.valueSuffix;
      });
    }
  }
  function autoSelectServer() {
    $("#node_alert").show();
    $("#node_alert").html($.t("trying_auto_connection"));
    $("#brs_version, #brs_version_dashboard").html(BRS.loadingDotsHTML).addClass("loading_dots");
    const mainnetServers = BRS.nodes.filter((obj) => obj.testnet === false).slice(1);
    for (let i = mainnetServers.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [mainnetServers[i], mainnetServers[j]] = [mainnetServers[j], mainnetServers[i]];
    }
    mainnetServers.unshift(BRS.nodes[0]);
    const responses = [];
    setTimeout(() => {
      responses.sort((a, b) => b[2] - a[2]);
      $("#prefered_node").val(responses[0][0]);
      getState();
    }, 2100);
    for (const server of mainnetServers) {
      $.ajax({
        url: `${server.address}/burst?requestType=getBlock`,
        crossDomain: true,
        dataType: "json",
        type: "GET",
        timeout: 2e3,
        async: true
      }).done(function(response, status) {
        if (status === "success" && response.errorCode === void 0) {
          const fasterResponse = responses.find((row) => row[1] === response.block);
          if (fasterResponse) {
            fasterResponse[2] = fasterResponse[2] + 1;
            return;
          }
          responses.push([server.address, response.block, 1]);
        }
      });
    }
  }
  async function getState() {
    checkSelectedNode();
    const response = await sendRequest("getBlockchainStatus+", {});
    if (response.errorCode) {
      if (BRS.settings.automatic_node_selection) {
        autoSelectServer();
        return;
      }
      $("#node_alert").show();
      $("#node_alert").html($.t("could_not_connect_to", { server: BRS.server }));
      $("#brs_version, #brs_version_dashboard").html(BRS.loadingDotsHTML).removeClass("loading_dots");
      $("#prefered_node").addClass("is-invalid");
      return;
    }
    $("#node_alert").hide();
    BRS.blockchainStatus = response;
    $("#brs_version").html(response.version + " on " + BRS.server).removeClass("loading_dots");
    $("#brs_version_dashboard").html(response.version).removeClass("loading_dots");
    $("#header_current_block").html("#" + response.numberOfBlocks);
    $("#prefered_node").removeClass("is-invalid");
  }
  function init2() {
    try {
      window.localStorage.setItem("test", "1");
      window.localStorage.removeItem("test");
      BRS.hasLocalStorage = true;
    } catch {
      BRS.hasLocalStorage = false;
    }
    $("#neoclassic_version").html(BRS.version);
    if (!window.crypto || !window.crypto.subtle) {
      notify($.t("error_encryption_browser_support"));
      return;
    }
    createDatabase(loadAllDBValues);
    setTimeout(function() {
      if (BRS.settings.automatic_node_selection) {
        autoSelectServer();
      } else {
        getState();
        BRS.stateInterval = setInterval(getState, 1e4);
      }
      showLockscreen();
    }, 250);
    automaticallyCheckRecipient();
  }
  function loadAllDBValues() {
    loadContactsFromDB();
    loadClosedGroupsFromDB();
    loadAssetsFromDB();
    loadSettingsFromDB();
  }
  function showLockscreen() {
    showLoginOrWelcomeScreen();
    $("#lockscreen_loading").hide();
    $("#lockscreen_content").show();
    populateRecipientSelector($("#login_panel"));
    populateNodeSelector($(".node_selector"));
  }
  function populateNodeSelector($target) {
    const $list = $target.find("ul");
    $list.empty();
    if (BRS.settings.automatic_node_selection) {
      $list.append("<li class='divider'></li>");
      return;
    }
    for (const server of BRS.nodes.filter((obj) => obj.testnet === false)) {
      $list.append("<li><a class='dropdown-item' href='#' data-server='" + server.address + "'>" + server.address + "</a></li>");
    }
    $list.append("<li><hr class='dropdown-divider'></li>");
    for (const server of BRS.nodes.filter((obj) => obj.testnet === true)) {
      $list.append("<li><a class='dropdown-item' href='#' data-server='" + server.address + "'>" + server.address + "</a></li>");
    }
    $list.on("click", "li a", function(e) {
      e.preventDefault();
      $(this).closest("div").find("input[name=prefered_node]").val($(this).data("server")).trigger("blur");
    });
  }
  function showLoginOrWelcomeScreen() {
    if (BRS.hasLocalStorage && localStorage.getItem("logged_in")) {
      showLoginScreen();
    } else {
      showWelcomeScreen();
    }
  }
  function showLoginScreen() {
    $("#account_phrase_custom_panel, #account_phrase_generator_panel, #welcome_panel, #custom_passphrase_link").hide();
    $("#account_phrase_custom_panel :input:not(:button):not([type=submit])").val("");
    $("#account_phrase_generator_panel :input:not(:button):not([type=submit])").val("");
    $("#login_panel").show();
    setTimeout(function() {
      $("#login_password").trigger("focus");
    }, 10);
  }
  function showWelcomeScreen() {
    $(
      "#login_panel, account_phrase_custom_panel, #account_phrase_generator_panel, #account_phrase_custom_panel, #welcome_panel, #custom_passphrase_link"
    ).hide();
    $("#welcome_panel").show();
  }

  // src/js/brs/core/context_menu.ts
  function evWidgetContextMenuOnContextmenuA(e) {
    e.preventDefault();
    closeContextMenu();
    const clickedElement = $(e.currentTarget);
    if (clickedElement.hasClass("no-context")) {
      return;
    }
    BRS.selectedContext = clickedElement;
    $(document).on("click.contextmenu", closeContextMenu);
    const contextMenu = clickedElement.data("context");
    const $contextMenu = $("#" + contextMenu);
    if ($contextMenu.length) {
      const $options = $contextMenu.find("ul.dropdown-menu a");
      $.each($options, function() {
        const requiredClass = $(this).data("class");
        if (!requiredClass) {
          $(this).show();
        } else if (clickedElement.hasClass(requiredClass)) {
          $(this).show();
        } else {
          $(this).hide();
        }
      });
      $contextMenu.css({
        display: "block",
        left: e.pageX,
        top: e.pageY
      });
    }
  }
  function closeContextMenu() {
    $(".context_menu").hide();
    if (BRS.selectedContext) {
      BRS.selectedContext = null;
    }
    $(document).off("click.contextmenu");
  }
  function evWidgetContextMenuOnContextClickA(e) {
    e.preventDefault();
    if (!BRS.selectedContext) return;
    const currentContext = BRS.selectedContext.data("context");
    const option = $(e.currentTarget).data("option");
    const item = BRS.selectedContext.data("item");
    closeContextMenu();
    switch (currentContext) {
      case "messages_vtab_context":
        messagesVtabContextHandler(option, item);
        break;
      case "asset_exchange_vtab_context":
        assetExchangeVtabContextHandler(option, item);
        break;
      case "asset_exchange_vtab_group_context":
        assetExchangeVtabGroupContextHandler(option, item);
        break;
      default:
        console.error("Unknown context: " + currentContext);
    }
  }

